// The Builder Kit's settings deny list (builder-kit/settings.json permissions.deny, Claude Code
// syntax) as one shared check: Claude Code enforces it natively; on OpenCode chats the app turns
// it into OpenCode permission rules (src/engines/opencode.js translateDeny) AND the guard plugin
// (ninja-guard.js) enforces it on every call with this matcher. A rule this file can't read
// fails closed: the OpenCode chat does not start, and the guard blocks every call.
//
// Rule forms (Claude Code permissions):
//   Tool                     every call of that tool
//   Bash(npm run test:*)     prefix (legacy ":*"), Bash(git push *) glob — on every simple command
//                            the line runs (shell-parse.mjs: subshells, $( ), -c payloads, wrappers…);
//                            a line it can't parse is blocked
//   Read(~/.ssh/**)          paths, gitignore-style: //abs, ~/home, /project-root, ./ or bare = cwd;
//   Edit(…) Write(…)         Read rules also cover Glob / Grep / LS; Edit rules cover Write / MultiEdit;
//                            symlinks resolved, case-insensitive on macOS / Windows
//   WebFetch(domain:x.com)   that host and its subdomains
//   mcp__server / mcp__server__tool (or mcp__server__*)
import path from 'node:path';
import fs from 'node:fs';
import { commandUnits, ShellParseError } from './shell-parse.mjs';

const PATH_TOOLS = new Set(['Read', 'Edit', 'Write', 'MultiEdit', 'NotebookEdit', 'Glob', 'Grep', 'LS']);
const KNOWN = new Set(['Bash', 'WebFetch', 'WebSearch', 'Agent', 'Task', 'Skill', 'TodoWrite', ...PATH_TOOLS]);

// → { tool, spec|null, raw } — throws on a rule it can't read.
export function parseDenyRule(raw) {
    const s = String(raw == null ? '' : raw).trim();
    const m = /^([A-Za-z_][A-Za-z0-9_]*)(?:\(([\s\S]*)\))?$/.exec(s);
    if (!m) throw new Error(`can't read the deny rule "${s}"`);
    const tool = m[1];
    const spec = m[2] === undefined ? null : m[2];
    if (/^mcp__/.test(tool)) {
        if (spec !== null) throw new Error(`can't read the deny rule "${s}"`);
        return { tool, spec: null, raw: s };
    }
    if (!KNOWN.has(tool)) throw new Error(`unknown tool in the deny rule "${s}"`);
    if (spec !== null && !spec.trim()) throw new Error(`empty deny rule "${s}"`);
    if (tool === 'WebFetch' && spec !== null && !/^domain:[A-Za-z0-9.*-]+$/.test(spec.trim())) throw new Error(`can't read the deny rule "${s}"`);
    if (!PATH_TOOLS.has(tool) && !['Bash', 'WebFetch'].includes(tool) && spec !== null) throw new Error(`can't read the deny rule "${s}"`);
    return { tool, spec, raw: s };
}
// Every rule, or throws naming the first one it can't read.
export function parseDenyList(list) {
    if (!Array.isArray(list)) throw new Error('the deny list is not a list');
    return list.map(parseDenyRule);
}

// A glob → RegExp. pathMode: '*' stays inside one folder, '**' crosses folders. nocase: for
// case-insensitive file systems (macOS, Windows).
export function globRegex(glob, pathMode, nocase = false) {
    let re = '';
    const g = String(glob);
    for (let i = 0; i < g.length; i++) {
        const c = g[i];
        if (c === '*') {
            if (pathMode && g[i + 1] === '*') {
                i++;
                if (g[i + 1] === '/') { i++; re += '(?:.*/)?'; } else re += '.*';
            } else re += pathMode ? '[^/]*' : '[\\s\\S]*';
        } else if (c === '?') re += pathMode ? '[^/]' : '[\\s\\S]';
        else re += c.replace(/[.+^${}()|[\]\\]/g, '\\$&');
    }
    return new RegExp(`^${re}$`, nocase ? 'i' : '');
}

// A path rule's spec → an absolute glob.
export function absRuleGlob(spec, { cwd, home, projectRoot }) {
    const s = String(spec).trim();
    if (s.startsWith('//')) return path.posix.normalize(s.slice(1));
    if (s === '~' || s.startsWith('~/')) return path.posix.join(home, s.slice(1));
    if (s.startsWith('/')) return path.posix.join(projectRoot || cwd, s);
    return path.posix.join(cwd, s);
}

// The path with its longest existing prefix resolved through symlinks (the rest kept as is):
// a link into ~/.ssh is checked as the ~/.ssh path it really is.
export function realPrefix(p, realpath = (x) => fs.realpathSync(x)) {
    let cur = path.posix.normalize(String(p));
    const rest = [];
    for (let k = 0; k < 256; k++) {
        try { return path.posix.join(realpath(cur), ...rest.reverse()); } catch { /* go up */ }
        const parent = path.posix.dirname(cur);
        if (parent === cur) return path.posix.normalize(String(p));
        rest.push(path.posix.basename(cur));
        cur = parent;
    }
    return path.posix.normalize(String(p));
}
// A glob with its literal folder (before the first wildcard) resolved the same way.
function realGlob(g, realpath) {
    const i = g.search(/[*?]/);
    if (i < 0) return realPrefix(g, realpath);
    const cut = g.lastIndexOf('/', i);
    if (cut <= 0) return g;
    return `${realPrefix(g.slice(0, cut), realpath)}${g.slice(cut)}`;
}

// A command that can't be parsed: blocked when any Bash rule exists.
export const UNPARSEABLE = { tool: 'Bash', spec: null, raw: 'a command Ninja Builder could not read' };

// Every simple command and pipeline a command line runs (shell-parse.mjs), plus the whole line
// (whitespace collapsed) for rules written against the full text. null = can't be parsed.
export function bashCandidates(command) {
    // A control character (other than tab / newline) anywhere — even one trim() would drop — can't be read.
    if (/[\x00-\x08\x0b-\x1f]/.test(String(command || ''))) return null;
    const cmd = String(command || '').trim();
    if (!cmd) return { units: [], pipelines: [], whole: '' };
    let r;
    try { r = commandUnits(cmd); } catch (e) { if (e instanceof ShellParseError) return null; throw e; }
    return { units: r.units, pipelines: r.pipelines, whole: cmd.replace(/\s+/g, ' ') };
}
function bashMatches(spec, cand) {
    // A pipe-shaped rule ("curl* | sh") matches a pipeline, whitespace around | normalized.
    const s = spec.trim().replace(/\s*\|\s*/g, ' | ');
    const prefix = /:\*$/.test(s) ? s.slice(0, -2) : null;
    const re = prefix === null ? globRegex(s, false) : null;
    const hit = (p) => (prefix !== null ? p === prefix || p.startsWith(prefix) : re.test(p));
    const list = s.includes(' | ') ? [...cand.pipelines, cand.whole.replace(/\s*\|\s*/g, ' | ')] : [...cand.units, cand.whole];
    return list.some((p) => p && hit(p));
}
function pathMatches(spec, p, ctx) {
    if (!p) return false;
    const abs = path.posix.isAbsolute(p) ? path.posix.normalize(p) : path.posix.join(ctx.cwd, p);
    const g = absRuleGlob(spec, ctx);
    const nocase = ctx.platform === 'darwin' || ctx.platform === 'win32';
    const test = (a, glob) => {
        const re = globRegex(glob, true, nocase);
        // A folder rule ("x/**") also covers the folder itself.
        const dir = /\/\*\*$/.test(glob) ? glob.slice(0, -3) : null;
        return re.test(a) || (dir !== null && (nocase ? a.toLowerCase() === dir.toLowerCase() : a === dir));
    };
    const realA = realPrefix(abs, ctx.realpath);
    const realG = realGlob(g, ctx.realpath);
    return test(abs, g) || test(realA, g) || test(realA, realG) || test(abs, realG);
}
// The host, lowercased, without trailing dots ("EVIL.example." is evil.example).
export const hostOf = (url) => { try { return new URL(String(url).toLowerCase()).hostname.replace(/\.+$/, ''); } catch { return ''; } };
export const ruleDomain = (spec) => String(spec).trim().slice('domain:'.length).toLowerCase().replace(/^\*\./, '').replace(/\.+$/, '');

// The rule a Claude-shaped call breaks, or null. call: { tool_name, tool_input, cwd }.
// opts.platform: case-insensitive paths on darwin / win32; opts.realpath: for tests.
export function matchDeny(rules, call, { home, projectRoot, platform = process.platform, realpath } = {}) {
    const tool = String((call && call.tool_name) || '');
    const input = (call && call.tool_input) || {};
    const ctx = { cwd: (call && call.cwd) || projectRoot || '/', home: home || '/', projectRoot: projectRoot || (call && call.cwd) || '/', platform, realpath: realpath || ((x) => fs.realpathSync(x)) };
    let cand;
    for (const r of rules) {
        if (/^mcp__/.test(r.tool)) {
            const t = r.tool.replace(/__\*$/, '');
            if (tool === t || tool.startsWith(`${t}__`)) return r;
            continue;
        }
        const same = r.tool === tool || (r.tool === 'Task' && tool === 'Agent') || (r.tool === 'Agent' && tool === 'Task')
            || (r.tool === 'Read' && ['Glob', 'Grep', 'LS'].includes(tool))
            || (r.tool === 'Edit' && ['Write', 'MultiEdit', 'NotebookEdit'].includes(tool));
        if (!same) continue;
        if (r.spec === null) return r;
        if (r.tool === 'Bash') {
            if (cand === undefined) cand = bashCandidates(input.command);
            if (cand === null) return UNPARSEABLE;
            if (bashMatches(r.spec, cand)) return r;
            continue;
        }
        if (r.tool === 'WebFetch') {
            const d = ruleDomain(r.spec);
            const h = hostOf(input.url);
            if (h && (h === d || h.endsWith(`.${d}`))) return r;
            continue;
        }
        if (PATH_TOOLS.has(r.tool)) {
            const p = input.file_path || input.path || input.notebook_path || '';
            if (pathMatches(r.spec, p, ctx)) return r;
            // A search with no path searches its folder.
            if (!p && ['Glob', 'Grep', 'LS'].includes(tool) && pathMatches(r.spec, ctx.cwd, ctx)) return r;
        }
    }
    return null;
}

// The same rules as OpenCode permission rules (native, first line of defence; the guard is the
// second). action/resource as OpenCode 2.2.5 names them.
const OC_ACTIONS = { Bash: ['shell'], Read: ['read', 'glob', 'grep', 'list'], Edit: ['edit'], Write: ['edit'], MultiEdit: ['edit'], NotebookEdit: ['edit'],
    Glob: ['glob'], Grep: ['grep'], LS: ['list'], WebFetch: ['webfetch'], WebSearch: ['websearch'], Agent: ['subagent'], Task: ['subagent'], Skill: ['skill'], TodoWrite: ['todowrite'] };
export function toOpenCodeRules(rules, ctx) {
    const out = [];
    for (const r of rules) {
        if (/^mcp__/.test(r.tool)) {
            const [, server, t] = /^mcp__(.+?)(?:__(.+))?$/.exec(r.tool);
            out.push({ action: t && t !== '*' ? `${server}_${t}` : `${server}_*`, resource: '*', effect: 'deny' });
            continue;
        }
        let resource = '*';
        if (r.spec !== null) {
            if (r.tool === 'Bash') resource = /:\*$/.test(r.spec.trim()) ? `${r.spec.trim().slice(0, -2)}*` : r.spec.trim();
            else if (r.tool === 'WebFetch') resource = `*${ruleDomain(r.spec)}*`; // lowercased, no trailing dot
            else resource = absRuleGlob(r.spec, ctx);
        }
        for (const action of OC_ACTIONS[r.tool]) out.push({ action, resource, effect: 'deny' });
    }
    return out;
}

files.opencode/kit-hooks.mjs:
// The Builder Kit's hooks (job-guard, review-gate, brief-gate, done-gate, target-gate,
// discipline, lessons…) for OpenCode chats. Claude Code runs them from each plugin's
// hooks/hooks.json; OpenCode has no such hooks, so Ninja Builder runs the SAME scripts the
// same way: one process per hook, the Claude-shaped event as JSON on stdin, and Claude's
// reading of the answer (exit 2 = block with stderr as the reason; stdout JSON
// hookSpecificOutput = extra context or a changed input; anything else = carry on).
//
//   PreToolUse        the guard plugin (ninja-guard.js, tool.execute.before), after the risk gate
//   Stop              the app, when a reply ends (src/engines/opencode.js): a block sends the
//                     reason back as "Stop hook feedback" and the reply goes on, as on Claude
//   UserPromptSubmit  the app, before each message: extra context goes with the message
//   SessionStart      the app, when the chat's server starts: extra context goes with the first message
//
// Only the kit's own scripts run (a hooks.json command must name a .mjs file inside the kit's
// hooks folder); risk-gate is not in the list: the guard runs it in-process and fails closed.
// Like Claude Code, a hook that crashes, times out or can't start does not block (exit 2 only).
// No I/O at import: the app and the plugin (inside OpenCode's own binary) both load it.
import path from 'node:path';

export const EVENTS = ['PreToolUse', 'Stop', 'UserPromptSubmit', 'SessionStart'];
// In-process elsewhere (the guard plugin's risk gate) or Claude-only (live-notes rewrites a
// Workflow script; OpenCode has no Workflow tool).
const SKIP = new Set(['risk-gate.mjs', 'live-notes.mjs']);
export const HOOK_TIMEOUT_MS = 30000;

// One plugin's hooks.json → [{ event, matcher, script }] with each script resolved to an
// absolute .mjs inside `hooksDir` (the kit's plugin/hooks). Commands that don't name one are
// left out (never run as a shell command).
export function hooksFromJson(json, hooksDir) {
    const out = [];
    const all = json && typeof json === 'object' && json.hooks && typeof json.hooks === 'object' ? json.hooks : {};
    const root = path.resolve(hooksDir);
    for (const event of EVENTS) {
        for (const group of Array.isArray(all[event]) ? all[event] : []) {
            const matcher = typeof (group && group.matcher) === 'string' ? group.matcher : '';
            for (const h of Array.isArray(group && group.hooks) ? group.hooks : []) {
                const cmd = String((h && h.command) || '');
                const m = /([A-Za-z0-9_-]+\.mjs)"?(\s|$)/.exec(cmd);
                if (!m || SKIP.has(m[1])) continue;
                const script = path.join(root, m[1]);
                if (path.dirname(script) !== root) continue;
                out.push({ event, matcher, script });
            }
        }
    }
    return out;
}

// Several plugins' lists → one, each script once per event and matcher.
export function mergeHooks(lists) {
    const seen = new Set();
    const out = [];
    for (const h of lists.flat()) {
        const k = `${h.event}|${h.matcher}|${h.script}`;
        if (seen.has(k)) continue;
        seen.add(k);
        out.push(h);
    }
    return out;
}

// Claude Code's matcher: '' or '*' = every tool; otherwise a regex over the tool's name.
export function matches(matcher, toolName) {
    const m = String(matcher || '');
    if (!m || m === '*') return true;
    try { return new RegExp(`^(?:${m})$`).test(String(toolName || '')); } catch { return false; }
}
export function hooksFor(list, event, toolName = '') {
    return (Array.isArray(list) ? list : []).filter((h) => h && h.event === event && (event !== 'PreToolUse' || matches(h.matcher, toolName)));
}

// A hook process's outcome → { block, reason, context, updatedInput } (Claude's rules).
/** @param {{ code?: number|null, stdout?: string, stderr?: string }} [r] @param {string} [event] */
export function interpret({ code = null, stdout = '', stderr = '' } = {}, event = 'PreToolUse') {
    if (code === 2) return { block: true, reason: String(stderr || '').trim() || 'Blocked by a Builder Kit hook.' };
    if (code !== 0) return { block: false };
    let j = null;
    const s = String(stdout || '').trim();
    if (s.startsWith('{')) { try { j = JSON.parse(s); } catch { j = null; } }
    const o = j && j.hookSpecificOutput && typeof j.hookSpecificOutput === 'object' ? j.hookSpecificOutput : {};
    const out = { block: false };
    if (j && j.decision === 'block') return { block: true, reason: String(j.reason || '').trim() || 'Blocked by a Builder Kit hook.' };
    if (typeof o.additionalContext === 'string' && o.additionalContext.trim()) out.context = o.additionalContext.trim();
    if (event === 'PreToolUse' && o.updatedInput && typeof o.updatedInput === 'object') out.updatedInput = o.updatedInput;
    return out;
}

// Run one hook script: `runtime.command [...runtime.args] script` with `input` as JSON on stdin.
// spawnFn is node:child_process spawn (injected: the plugin and the app pass their own).
// → Promise<{ code, stdout, stderr }> (code null = could not start or timed out).
export function runHook({ spawnFn, runtime, script, input, env, cwd, timeoutMs = HOOK_TIMEOUT_MS }) {
    return new Promise((resolve) => {
        let child;
        let out = '';
        let err = '';
        let done = false;
        const finish = (code) => { if (done) return; done = true; clearTimeout(timer); resolve({ code, stdout: out, stderr: err }); };
        const timer = setTimeout(() => { try { child && child.kill('SIGKILL'); } catch { /* gone */ } finish(null); }, timeoutMs);
        try {
            child = spawnFn(runtime.command, [...(runtime.args || []), script], { cwd: cwd || undefined, env: { ...env, ...(runtime.env || {}) }, stdio: ['pipe', 'pipe', 'pipe'], windowsHide: true });
        } catch { finish(null); return; }
        child.stdout.on('data', (d) => { if (out.length < 200000) out += d.toString(); });
        child.stderr.on('data', (d) => { if (err.length < 200000) err += d.toString(); });
        child.on('error', () => finish(null));
        child.on('close', (code) => finish(code));
        try { child.stdin.on('error', () => {}); child.stdin.end(JSON.stringify(input || {})); } catch { /* it exits */ }
    });
}

// Every hook of `event` (for `toolName`) in order; the first block wins, contexts are joined.
// → { block, reason, context, updatedInput }
export async function runEvent(list, event, input, opts) {
    const ctx = [];
    let updatedInput;
    for (const h of hooksFor(list, event, input && input.tool_name)) {
        const r = interpret(await runHook({ ...opts, script: h.script, input: { ...input, hook_event_name: event, ...(updatedInput ? { tool_input: updatedInput } : {}) } }), event);
        if (r.block) return { block: true, reason: r.reason };
        if (r.context) ctx.push(r.context);
        if (r.updatedInput) updatedInput = r.updatedInput;
    }
    return { block: false, ...(ctx.length ? { context: ctx.join('\n\n') } : {}), ...(updatedInput ? { updatedInput } : {}) };
}

files.opencode/netns-bridge.mjs:
// Runs INSIDE a Linux OpenCode chat's sandbox (bubblewrap, its own network namespace with no
// network), started by OpenCode's own binary as Bun (BUN_BE_BUN=1) — see
// src/engines/opencode-sandbox.js buildBwrapSandbox. It is the namespace's only way out, and
// only to the app:
//   - each 127.0.0.1:<port> the chat may reach (the egress proxy, the app's own port) is a
//     listener here that forwards to a unix socket the app serves on the host side;
//   - the OpenCode server it starts (the rest of argv) listens on 127.0.0.1 in here; the app
//     reaches it through a unix socket the APP made, in a folder this sandbox can only read: its
//     listening descriptor arrives as fd AIB_BRIDGE.apiFd (3), and this accepts on it.
// It exits with the server (and stops it when it is stopped).
import net from 'node:net';
import { spawn } from 'node:child_process';

const cfg = JSON.parse(process.env.AIB_BRIDGE || '{}');
const childEnv = { ...process.env };
delete childEnv.AIB_BRIDGE;
delete childEnv.BUN_BE_BUN;
const pipe = (a, b) => { a.on('error', () => b.destroy()); b.on('error', () => a.destroy()); a.pipe(b); b.pipe(a); };
const listen = (server, ...where) => new Promise((resolve, reject) => { server.once('error', reject); server.listen(...where, resolve); });

for (const f of Array.isArray(cfg.forwards) ? cfg.forwards : []) {
    await listen(net.createServer((c) => pipe(c, net.connect(f.socket))), Number(f.port), '127.0.0.1');
}
const [cmd, ...args] = process.argv.slice(2);
// The server gets stdio only: the API descriptor stays with the bridge.
const child = spawn(cmd, args, { env: childEnv, stdio: ['ignore', 'pipe', 'inherit'] });
for (const sig of ['SIGTERM', 'SIGINT', 'SIGHUP']) process.on(sig, () => { try { child.kill(sig); } catch { /* gone */ } });
child.on('exit', (code, sig) => process.exit(code == null ? (sig ? 1 : 0) : code));
let buf = '';
let up = false;
child.stdout.on('data', async (d) => {
    if (up) { process.stdout.write(d); return; }
    buf += d.toString();
    const m = /listening on https?:\/\/127\.0\.0\.1:(\d{2,5})/.exec(buf);
    if (!m) return;
    up = true;
    const port = Number(m[1]);
    await listen(net.createServer((c) => pipe(c, net.connect(port, '127.0.0.1'))), { fd: Number(cfg.apiFd) });
    process.stdout.write(buf);
    buf = '';
});

files.opencode/ninja-guard.js:
// Ninja Builder's guard plugin for OpenCode chats (beta). The app copies it into each chat's
// private OpenCode config dir (plugins/), next to an app-owned opencode.json. It does two things:
//
//  1. risk-gate on EVERY tool call, in both hooks OpenCode gives a plugin:
//     tool.execute.before (the full input, runs first) and permission.evaluate (the permission
//     request: an action plus resources, e.g. a shell command split into its parts). Each runs
//     the SAME gate as Claude chats (builder-kit/plugin/hooks/risk-gate.mjs → evaluateToolCall):
//       - the call itself, Claude-shaped: built-in tools under Claude's names (anything that
//         runs code is Bash, tool_input.command = exactly the field it runs), MCP tools as
//         mcp__<server>__<tool> so the per-server rules (tracker read-only…) match; it runs in
//         the chat's folder (AIB_CWD) — only a shell may name another, through `workdir`; a
//         workdir / cwd / directory field on any other built-in tool is denied;
//       - then EVERY string on the call — input, metadata and resources, nested fields walked
//         with their full key path:
//           built-in tools: under a code key anywhere on the path → a Bash command; under a path
//           key → a path (made absolute first); under a URL key → a fetch; a search pattern →
//           its literal root as a path (an absolute or ~ pattern outside the project is denied);
//           the tool's own known text fields → data; anything else → denied.
//           MCP tools: every string, whatever its key, is checked as a command, a path AND a URL.
//     It FAILS CLOSED: a gate that can't be loaded, throws or answers nonsense, a tool it can't
//     name, a field it can't classify, a call too large to walk, and a code permission request
//     whose full command it never saw (resources only) — all block.
//  2. shell env: the provider API keys and the server's own password are passed to OpenCode as
//     env; without this hook every shell the agent runs could print them. They are removed, and
//     the person's own XDG_* folders are put back (the server runs with app-owned ones).
//  3. the rest of the Builder Kit's PreToolUse hooks (job-guard, review-gate, brief-gate…), run
//     after the risk gate passes, exactly as Claude Code runs them (kit-hooks.mjs): one process
//     each, the Claude-shaped call on stdin, exit 2 blocks with its reason.
//  4. plan mode ("Plan first", set by the app in AIB_MODE_FILE — not by the agent's name, which
//     a subagent doesn't share): every call of the chat and of its subagents may read and look
//     things up only — no file writes, no command that changes anything, no subagent but `explore`.
//  5. skills: only the chat's own (the Builder Kit's) — never one OpenCode found elsewhere.
//
// Settings come from the server's env (set by src/engines/opencode.js):
//   AIB_RISK_GATE   absolute path of risk-gate.mjs        AIB_AUTONOMY  build | check | approve
//   AIB_GUARD_ONLY  '1' = only the always-on guards       AIB_STRIP_ENV comma list of names to remove
//   AIB_USER_XDG    JSON {XDG_DATA_HOME: '…' | null, …}   the person's own values (null = unset)
//   AIB_MCP_SERVERS comma list of the chat's MCP servers  AIB_TOOL_NAMES path of tool-names.mjs
//   AIB_CWD         the chat's folder (the project)       (default: the kit's, next to risk-gate's)
//   AIB_DENY_RULES  JSON: the settings deny list (Claude syntax), enforced with deny-rules.mjs
//                   on every gate call; a rule it can't read blocks every call
//   AIB_GUARD_TRACE a file to log every request to (debugging only; off by default)
//   AIB_HOOKS       JSON [{event:'PreToolUse', matcher, script}] — the kit's hook scripts (each must
