    Read: [],
    Write: ['content'],
    Edit: ['oldString', 'newString', 'old_string', 'new_string', 'content', 'patch', 'status'],
    MultiEdit: ['oldString', 'newString', 'old_string', 'new_string', 'patch', 'status'],
    Glob: [],
    Grep: [],
    LS: [],
