export const FOLDER_FLAGS = {
    env: { short: 'C', long: ['chdir'] },
    sudo: { short: 'D', long: ['chdir'] },
    git: { short: 'C', long: ['work-tree', 'git-dir'] },
    make: { short: 'C', long: ['directory'] },
    gmake: { short: 'C', long: ['directory'] },
    tar: { short: 'C', long: ['directory'] },
    bsdtar: { short: 'C', long: ['directory'] },
    npm: { short: 'C', long: ['prefix'] },
    npx: { short: '', long: ['prefix'] },
    pnpm: { short: 'C', long: ['prefix', 'dir'] },
    yarn: { short: '', long: ['cwd'] },
