// NAME=value prefixes that move where a command works (or where ~ points).
export const FOLDER_VAR = /^(GIT_DIR|GIT_WORK_TREE|npm_config_prefix|HOME|USERPROFILE|PWD|OLDPWD|[A-Za-z_][A-Za-z0-9_]*(_DIR|PREFIX|CWD))$/i;
const baseName = (w) => String(w).replace(/^.*[\\/]/, '').replace(/\.(exe|cmd|bat)$/i, '').toLowerCase();
// The path with its longest existing prefix resolved through links; null when that fails.
export function realDir(p) {
    // Any link on the way that points nowhere (yet): refused — its target could be made later.
    const abs = path.resolve(String(p));
    const parts = abs.split(path.sep);
    for (let k = 1; k <= parts.length; k++) {
        const pre = parts.slice(0, k).join(path.sep) || path.sep;
        let st = null;
        try { st = fs.lstatSync(pre); } catch { break; }
        if (st.isSymbolicLink() && !fs.existsSync(pre)) return null;
    }
    let cur = abs;
    const rest = [];
    for (let k = 0; k < 256; k++) {
        if (fs.existsSync(cur)) {
            try { return path.join(fs.realpathSync.native ? fs.realpathSync.native(cur) : fs.realpathSync(cur), ...rest.reverse()); } catch { return null; }
        }
