}
export function strictUnresolvable(command, { parse, projectRoot = '' } = {}) {
    const raw = String(command || '');
    if (!parse || typeof parse.rawCommands !== 'function') return 'Ninja Builder could not load its command reader';
    let cmds;
    let units;
    try { cmds = parse.rawCommands(raw); units = parse.commandUnits(raw).units; } catch { return 'Ninja Builder could not read it'; }
    // The literal text: every quote, escape and expansion changes what a word becomes.
    if (/["'\\`]/.test(raw)) return 'it uses quotes or escapes, so its words are not what they look like';
    const words = cmds.flat();
    if (words.some((w) => /\$|%[^%\s]+%/.test(w))) return 'it uses a variable or a substitution ($NAME, %NAME%, $(…))';
    // Globs and braces: the shell turns them into paths the guard never sees.
    if (words.some((w) => /[{}*?[\]]/.test(w))) return 'it uses a wildcard or a brace ({ } * ? [ ]), which the shell turns into paths Ninja Builder can\'t check';
