            const asg = /^([A-Za-z_][A-Za-z0-9_]*)=(.*)$/.exec(w0);
            if (asg && FOLDER_VAR.test(asg[1]) && !okDir(asg[2])) return `${asg[1]}= must name a full path inside the project`;
            const tool = baseName(w0);
            const f = FOLDER_FLAGS[tool];
            if (!f) continue;
