// Does a command reach this folder by a RELATIVE path (or run in it)? Every word of the command
// (and the value after "=") is resolved against the folder the command runs in. Git Bash's
// /c/… form is read as C:/…. Case-insensitive (Windows, macOS volumes).
export function commandReaches(command, cwd, dir, home = os.homedir(), { strict = false } = {}) {
    const inDir = (p) => isInside(normCase(path.resolve(p)), normCase(path.resolve(dir)));
    // Could a path whose literal start is `root` lead into `dir` (a glob or a variable after it)?
    const mayReach = (root) => { const r = normCase(path.resolve(root)); const d = normCase(path.resolve(dir)); return isInside(r, d) || isInside(d, r); };
    if (cwd && inDir(cwd)) return true;
    const words = String(command || '').split(/[\s;|&<>()`]+/).flatMap((w) => [w, ...w.split('=').slice(1)]);
    for (let w of words) {
        w = w.replace(/^['"]+|['"]+$/g, '');
        // A value glued to a short flag (-Cpath, -o/x): check the value.
        const glued = /^-[A-Za-z]([^-].*)$/.exec(w);
        if (glued) w = glued[1];
        if (!w || w.startsWith('-')) continue;
        const drive = /^\/([a-zA-Z])(\/|$)/.exec(w);
        if (drive && process.platform === 'win32') w = `${drive[1]}:/${w.slice(3)}`;
        // Strict (no OS sandbox under the guard): a path with something the guard can't resolve —
        // a $VAR / %VAR% / ${…}, a glob or a {a,b} brace — fails closed when it could lead into dir.
        const special = w.search(/[$%*?[{]/);
        if (special >= 0) {
            if (!strict || !/[\\/]/.test(w)) continue;
            const lit = w.slice(0, special);
            if (!lit || /^[$%]/.test(w)) return true; // starts with a variable: could be anywhere
            const cut = Math.max(lit.lastIndexOf('/'), lit.lastIndexOf('\\'));
            if (mayReach(absPath(cut > 0 ? lit.slice(0, cut) : (cut === 0 ? '/' : '.'), cwd || '/', home))) return true;
            continue;
        }
        if (inDir(absPath(w, cwd || '/', home))) return true;
    }
    return false;
}
// Does a command name this folder (any slash style, Git Bash's /c/… form, ~ for the home)?
export function mentions(command, dir, home = os.homedir()) {
    const c = normCase(command);
