    const forms = new Set([d]);
    const drive = /^([a-z]):\//.exec(d);
    if (drive) forms.add(`/${drive[1]}/${d.slice(3)}`);
    const h = normCase(home).replace(/\/+$/, '');
    if (h && d.startsWith(`${h}/`)) { forms.add(`~/${d.slice(h.length + 1)}`); forms.add(`$home/${d.slice(h.length + 1)}`); forms.add(`\${home}/${d.slice(h.length + 1)}`); }
    return [...forms].some((f) => f && c.includes(f));
}

// A search pattern's literal root: the part before the first wildcard, cut back to a folder.
// '/Users/x/**/*.ts' → '/Users/x'; 'src/**' → 'src'; '*.txt' → ''.
export function patternRoot(pattern) {
    const p = String(pattern || '');
    const i = p.search(/[*?[{]/);
    const lit = i < 0 ? p : p.slice(0, i);
    if (i < 0) return lit;
    const cut = lit.lastIndexOf('/');
    return cut < 0 ? '' : (cut === 0 ? '/' : lit.slice(0, cut));
}
const rootedPattern = (p) => /^(\/|~(\/|$))/.test(String(p || '').trim());

// The tool's name for the gate. '' = unknown (denied).
function toolNameOf(ev, names, servers) {
    const action = String((ev && (ev.action || ev.tool)) || '');
    const meta = isObj(ev && ev.metadata) ? ev.metadata : {};
    let name = names.gateToolName(action, servers);
    if (!name && str(meta.server) && str(meta.tool) && /^[A-Za-z0-9_.-]+$/.test(meta.server + meta.tool)) name = `mcp__${meta.server}__${meta.tool}`;
    return { action, name };
