// Only OpenCode's shell runs in a folder of the call's choosing, and only through `workdir`.
// Every other tool works from the chat's folder: a `cwd` on a file tool must never move where
// its relative paths point.
export const WORKDIR_TOOLS = new Set(['shell', 'bash']);
export const FOLDER_KEYS = ['workdir', 'cwd', 'directory'];
const topInput = (ev) => {
    const meta = isObj(ev && ev.metadata) ? ev.metadata : {};
    return { ...(isObj(meta.input) ? meta.input : {}), ...(isObj(ev && ev.input) ? ev.input : {}) };
};
// A folder field on a built-in tool that has no such parameter (→ the call is denied), or ''.
export function strayFolderKey(ev, action, tool) {
    if (!tool || /^mcp__/.test(tool)) return '';
    const input = topInput(ev);
    for (const k of FOLDER_KEYS) {
        if (input[k] === undefined) continue;
        if (k === 'workdir' && WORKDIR_TOOLS.has(action)) continue;
        return k;
    }
    return '';
}
// The folder a call runs in: a shell's `workdir`, resolved against the chat's; else the chat's.
export function callCwd(ev, sessionCwd, home) {
    const action = String((ev && (ev.action || ev.tool)) || '');
    if (!WORKDIR_TOOLS.has(action)) return sessionCwd;
    const w = str(topInput(ev).workdir);
    return w ? absPath(w, sessionCwd, home) : sessionCwd;
}

// OpenCode's request (execute.before or permission.evaluate) → the Claude PreToolUse shape of
// the call itself, its paths made absolute. tool_name '' = a tool the gate can't name.
// has_command: a code tool's run field was present (false = only resources: not the full command).
export function claudeShape(ev, cwd, names, servers = [], home = os.homedir()) {
    const { action, name } = toolNameOf(ev, names, servers);
    const meta = isObj(ev && ev.metadata) ? ev.metadata : {};
    const res = Array.isArray(ev && ev.resources) ? ev.resources.filter((r) => typeof r === 'string') : [];
    const input = { ...(isObj(meta.input) ? meta.input : {}), ...(isObj(ev && ev.input) ? ev.input : {}) };
    let hasCommand = true;
    if (name === 'Bash') {
        // Exactly the field this tool runs (shell: command; execute: code, then script).
        const runFields = (names.CODE_FIELDS && names.CODE_FIELDS[action]) || ['command'];
        const run = runFields.map((f) => str(input[f]) || str(meta[f])).find(Boolean) || '';
        hasCommand = Boolean(run);
        for (const f of CODE_KEYS) delete input[f];
        input.command = run;
    }
    if (['Read', 'Edit', 'Write', 'MultiEdit'].includes(name)) {
        const fp = input.file_path || input.filePath || input.path || (res.length === 1 ? res[0] : '') || '';
        input.file_path = fp ? absPath(fp, cwd, home) : '';
        if (input.oldString !== undefined && input.old_string === undefined) input.old_string = input.oldString;
        if (input.newString !== undefined && input.new_string === undefined) input.new_string = input.newString;
    }
    if (name === 'Glob' || name === 'Grep' || name === 'LS') {
        const root = str(input.path) || str(meta.root) || (name === 'LS' && res.length === 1 ? res[0] : '');
        if (root) input.path = absPath(root, cwd, home);
    }
    return { tool_name: name, tool_input: input, cwd, opencode_tool: action, has_command: hasCommand };
}

// Every string on the call: input, metadata, resources, nested objects/arrays walked.
// → { items: [{ keys, key, where, value }], overflow } — keys: every object key from the top
// down to the string ('#resource' for a resource), key: the last of them.
export function collectStrings(ev) {
    const items = [];
    let overflow = false;
    const walk = (v, keys, where, depth) => {
        if (overflow) return;
        if (depth > MAX_DEPTH) { overflow = true; return; }
        if (typeof v === 'string') {
            if (items.length >= MAX_STRINGS) { overflow = true; return; }
            if (v.trim()) items.push({ keys, key: keys.length ? keys[keys.length - 1] : '', where, value: v });
            return;
        }
        if (Array.isArray(v)) { for (const x of v) walk(x, keys, where, depth + 1); return; }
        if (isObj(v)) for (const [k, x] of Object.entries(v)) walk(x, [...keys, k], where, depth + 1);
    };
    walk(ev && ev.input, [], 'input', 0);
    walk(ev && ev.metadata, [], 'metadata', 0);
    if (Array.isArray(ev && ev.resources)) for (const r of ev.resources) walk(r, ['#resource'], 'resources', 1);
    else if (ev && ev.resources != null) walk(ev.resources, ['#resource'], 'resources', 1);
    return { items, overflow };
}

// How one string is checked: 'code' | 'path' | 'url' | 'pattern' | 'text' | 'all' (an MCP tool's
// string: code, path and URL) | 'skip' | 'unknown' (denied).
export function classify(item, tool) {
    const keys = item.keys || (item.key ? [item.key] : []);
    const { value } = item;
    if (/^mcp__/.test(tool)) {
        if (keys[0] === '#resource' && value === '*') return 'skip';
        if (item.where === 'metadata' && keys.length === 1 && META_SKIP.has(keys[0])) return 'skip';
        return 'all';
    }
    if (keys[0] === '#resource') {
        if (value === '*') return 'skip';
        if (tool === 'Bash') return 'code';
        // Glob / Grep requests carry the search pattern as the resource (the folder is metadata.root).
        if (tool === 'Glob' || tool === 'Grep') return 'pattern';
        if (['Read', 'Edit', 'Write', 'MultiEdit', 'LS'].includes(tool)) return 'path';
        if (tool === 'WebFetch') return 'url';
        return 'all';
    }
    if (item.where === 'metadata' && keys.length === 1 && META_SKIP.has(keys[0])) return 'skip';
    if (keys.some((k) => CODE_KEYS.has(k))) return 'code';
    if (keys.some((k) => PATH_KEYS.has(k))) return 'path';
    if (keys.some((k) => URL_KEYS.has(k))) return 'url';
    if ((tool === 'Glob' || tool === 'Grep' || tool === 'LS') && keys.some((k) => PATTERN_KEYS.has(k))) return 'pattern';
    if ((TOOL_TEXT[tool] || []).includes(item.key)) return 'text';
    return 'unknown';
}

export function stripEnv(env, names) {
    const removed = [];
    if (!env || typeof env !== 'object') return removed;
    for (const k of Object.keys(env)) {
        if (names.includes(k) || /^OPENCODE_/.test(k) || /^AIB_(STRIP_ENV|USER_XDG|RISK_GATE|GUARD_ONLY|MCP_SERVERS|TOOL_NAMES|GUARD_TRACE|DENY_RULES|HOOKS|HOOK_BIN|SKILLS|PROTECT|MODE_FILE|INTEGRITY|STRICT_PATHS)$/.test(k)) { delete env[k]; removed.push(k); }
    }
    return removed;
}
export function restoreXdg(env, saved) {
    if (!env || !saved || typeof saved !== 'object') return;
    for (const [k, v] of Object.entries(saved)) {
        if (!/^XDG_[A-Z_]+$/.test(k)) continue;
        if (v == null) delete env[k]; else env[k] = String(v);
    }
