// Plan mode ("Plan first"): what the `plan` agent may not do. → '' or the reason.
export const PLAN_READ_TOOLS = new Set(['Read', 'Glob', 'Grep', 'LS', 'WebFetch', 'WebSearch', 'Skill', 'TodoWrite', 'TodoRead', 'AskUserQuestion']);
export function planModeBlock(tool, input, isReadOnlyBash) {
    const why = (what) => `BLOCKED — the chat is in plan mode ("Plan first"): ${what}. Research read-only, then write the plan as your reply; the person approves it before anything is built.`;
    if (/^mcp__/.test(tool) || PLAN_READ_TOOLS.has(tool)) return '';
    if (tool === 'Bash') {
