#!/bin/sh
# Linux OpenCode chats: the agent's shell. OpenCode runs each command as `$SHELL -c "<command>"`;
# this runs it in bash one level deeper inside the chat's sandbox, in a process namespace of its
# own (a fresh /proc), so a command can't read the OpenCode server's environment — the server
# password and the provider keys — through /proc. See src/engines/opencode-sandbox.js.
exec "${AIB_BWRAP:-bwrap}" --die-with-parent --unshare-pid --bind / / --dev-bind /dev /dev --proc /proc -- /bin/bash "$@"

