// A shell command line → every simple command it would run, for the settings deny list
// (deny-rules.mjs). Not a full shell, but it never guesses: anything it can't follow throws,
// and the caller blocks the command.
//
// FAIL CLOSED BY GRAMMAR: it follows only what it fully handles, and throws on the rest.
// Followed: ; & && || | |& and newlines; ( ) subshells; $( ), ` `, <( ) >( ) and $(( )) inside or
// outside double quotes; 'single' and "double" quotes and \ escapes; plain ${…} expansions;
// # comments; here-documents (a quoted delimiter's body is data). Each simple command is then
// unwrapped: NAME=value prefixes, env / command / builtin / exec / nohup / nice / time / timeout /
// xargs / sudo / doas / stdbuf (with their options), and bash|sh|zsh|dash|ksh|fish -c '…' (with
// only -c -e -u -x -l -i), env -S and eval payloads are parsed in turn.
// Thrown (= blocked): a reserved word in command position (if then else elif fi do done while
// until for in case esac select function coproc ! { } [[ ]]) and name() definitions; a ${…}
// whose body has a quote, a backslash or any $; $'…' and $"…" (also inside double quotes); a
// shell with any option other than -[euxli]+ / -…c… / one `--` anywhere on its line; a shell,
// eval, source or . to the right of a pipe, with a here-document, here-string or redirect, or
// reading -, /dev/stdin, /dev/fd/*, /proc/*/fd/* or a process substitution (kept in the words as
// /dev/fd/63); source / . without a file or with an option; a shell -c, env -S (any spelling:
// -S, -iS, -Sx, --split-string[=]) or eval payload with $( ), ` `, ${ or $VAR, and an env -S
// payload with a backslash; an unquoted here-document body with $( ), ` ` or ${.
// Every unquoted < or > ends the word it is glued to and is a redirect token of its own
// (bash<<<"…" is bash, <<<, "…"), so no word keeps an unquoted < or >; an fd number glued to it
// belongs to it (2>&1). Redirects (with targets) come out of a command before its head is worked
// out, and again after every wrapper; a shell, eval, source or . with any redirect, or on a line
// with any input redirect / here-string / here-document, is blocked. env takes only its own
// options (-i -v -u -C -P -S, --ignore-environment --unset --chdir --split-string); others block.

const MAX_DEPTH = 12;
const MAX_UNITS = 400;

export class ShellParseError extends Error {}

// → { commands: [[word…]…], pipelines: [[[word…]…]…] } for one line (no unwrapping).
function lex(src, depth) {
    if (depth > MAX_DEPTH) throw new ShellParseError('nested too deeply');
    const s = String(src);
    // Any C0 control character other than tab and newline (\r, \0, the redirect sentinel…) blocks:
    // nothing typed can pass for a token the lexer makes.
    if (/[\x00-\x08\x0b-\x1f]/.test(s)) throw new ShellParseError('a control character');
    const commands = [];   // finished simple commands (word arrays), including nested ones
    const pipelines = [];  // runs of 2+ simple commands joined by |
    let words = [];
    let word = null;       // current word (string) or null
    let pipe = [];
    let i = 0;
    let atStart = true;    // at the start of a simple command ({ and } are group words there)
    const heredocs = [];   // pending here-doc delimiters { delim, quoted, strip }
    let lineInput = false; // an input redirect, here-string or here-document anywhere on this line
    const nested = (inner) => {
        const r = lex(inner, depth + 1);
        commands.push(...r.commands);
        pipelines.push(...r.pipelines);
    };
    const endWord = () => { if (word !== null) { words.push(word); word = null; atStart = false; } };
    // Per command: does it read a here-document, and does it sit to the right of a pipe.
    let curHeredoc = false;
    let nextPiped = false;
    const endCommand = (op) => {
        endWord();
        if (words.length) {
            if (curHeredoc) words.heredoc = true;
            if (nextPiped) words.piped = true;
            commands.push(words);
        }
        curHeredoc = false;
        nextPiped = op === '|';
        if (op === '|') { if (words.length) pipe.push(words); }
        else {
            if (words.length) pipe.push(words);
            if (pipe.length > 1) pipelines.push(pipe);
            pipe = [];
        }
        words = [];
        atStart = true;
    };
    const add = (c) => { word = (word === null ? '' : word) + c; };
