        // blocked. (Blunt: a quoted { glued to a redirect blocks too.)
        if (word !== null && word.includes('{')) throw new ShellParseError('a named file descriptor ({…}> / {…}<)');
        let fd = '';
        if (word !== null && /^\d+$/.test(word)) { fd = word; word = null; } else endWord();
        if (op.includes('<')) lineInput = true;
        words.push(R + fd + op);
