        throw new ShellParseError('unclosed parenthesis');
    };
    const closeBacktick = (start) => {
        let j = start;
        while (j < s.length) {
            if (s[j] === '\\') { j += 2; continue; }
            if (s[j] === '`') return j;
            j++;
        }
        throw new ShellParseError('unclosed backtick');
    };
    // Index just past the closing " of a string starting at `start`; substitutions inside are parsed.
    const closeDouble = (start) => {
        let j = start;
        while (j < s.length) {
            const c = s[j];
            if (c === '\\') { j += 2; continue; }
