    builtin: { opts: new Set() },
    exec: { opts: new Set(['-a']) },
    nohup: { opts: new Set() },
    nice: { opts: new Set(['-n', '--adjustment']) },
    time: { opts: new Set(['-f', '--format', '-o', '--output']) },
    timeout: { opts: new Set(['-s', '--signal', '-k', '--kill-after']), positional: 1 },
    xargs: { opts: new Set(['-I', '-i', '-n', '-L', '-l', '-P', '-s', '-E', '-e', '-d', '-a', '--arg-file', '--delimiter', '--max-args', '--max-procs', '--replace']) },
