// A command line → every simple command it runs, unwrapped, as normalized strings, plus each
// pipeline as "a | b | c". Throws ShellParseError on anything it can't follow.
export function commandUnits(cmd, depth = 0) {
    if (depth > MAX_DEPTH) throw new ShellParseError('nested too deeply');
    const { commands, pipelines, lineInput } = lex(cmd, depth);
    const units = new Set();
    const pipes = new Set();
    const norm = (words) => {
        const u = unwrap(words, { input: lineInput });
        for (const p of u.payloads) {
            const sub = commandUnits(p, depth + 1);
            for (const x of sub.units) units.add(x);
            for (const x of sub.pipelines) pipes.add(x);
        }
        for (const t of u.stages) units.add(t);
