// Tests: the words of the line's first top-level command (nested ones are skipped).
export function lexWords(cmd) {
    const head = String(cmd).trim().split(/[\s<>|;&]/)[0];
    return [...(lex(cmd, 0).commands.find((c) => c[0] === head) || [])].map((x) => x.replace(R, ''));
