// OpenCode tool names → Claude Code tool names, shared by the app's event normaliser
// (src/engines/opencode-events.js: tool cards, Deliverables refresh, the Preview trigger) and the
// guard plugin (ninja-guard.js: the risk gate's rules are written for Claude's names).

// Built-in OpenCode tools (and permission actions) the gate knows.
export const TOOL_NAMES = {
    shell: 'Bash', bash: 'Bash', execute: 'Bash', terminal: 'Bash',
    read: 'Read', edit: 'Edit', write: 'Write', patch: 'Edit', multiedit: 'MultiEdit',
    glob: 'Glob', grep: 'Grep', list: 'LS', subagent: 'Agent',
    question: 'AskUserQuestion', skill: 'Skill', webfetch: 'WebFetch', websearch: 'WebSearch',
    todowrite: 'TodoWrite', todoread: 'TodoRead', external_directory: 'Read',
};
// Tools that run code: the gate checks them as Bash, with the code in tool_input.command.
export const CODE_TOOLS = new Set(['shell', 'bash', 'execute', 'terminal']);
// The input field each code tool actually runs. Any OTHER code-like field on the same call is
// checked by the gate too (a harmless `command` must not hide a harmful `code`).
export const CODE_FIELDS = { shell: ['command'], bash: ['command'], terminal: ['command'], execute: ['code', 'script'] };
export const CODE_LIKE_FIELDS = ['command', 'code', 'script', 'cmd', 'source'];

// MCP tools: OpenCode names them "<server>_<tool>" (or "<server>.<tool>", "<server>__<tool>",
// "<server>/<tool>"). Matched against the chat's configured servers, longest name first.
// → 'mcp__<server>__<tool>', or '' when no server matches.
export function mcpToolName(name, mcpServers = []) {
    const n = String(name || '');
    if (/^mcp__[^_].*__.+/.test(n)) return n;
    const servers = [...mcpServers].filter(Boolean).sort((a, b) => b.length - a.length);
    for (const s of servers) {
        for (const sep of ['__', '_', '.', '/']) {
            if (n.startsWith(s + sep) && n.length > s.length + sep.length) return `mcp__${s}__${n.slice(s.length + sep.length)}`;
        }
    }
    return '';
}

// For display (tool cards): built-in → Claude name, MCP → mcp__server__tool, else Capitalised.
export function claudeToolName(name, mcpServers = []) {
    const n = String(name || '');
    if (TOOL_NAMES[n]) return TOOL_NAMES[n];
    const mcp = mcpToolName(n, mcpServers);
    if (mcp) return mcp;
    return n ? n[0].toUpperCase() + n.slice(1) : 'Tool';
}

// For the gate (strict): built-in → Claude name; a configured MCP server's tool → its MCP name;
// anything else → '' (the guard denies a tool it can't name).
export function gateToolName(name, mcpServers = []) {
    const n = String(name || '');
    if (TOOL_NAMES[n]) return TOOL_NAMES[n];
    return mcpToolName(n, mcpServers);
}

