// AGENTS.md nudge. AGENTS.md (agents.md) is the project file other AI coding tools read —
// Codex, Cursor, VS Code, Kiro, Gemini CLI… On SessionStart, when the chat's folder is a
// real project (a manifest or a git repo) with no AGENTS.md in it or above it, this puts a
// one-paragraph note in the chat's context: create one with the agents-md skill. The agent
// writes the file from what it verifies in the repo; this hook only decides whether to ask.
// Never for the home folder, temporary/scratch folders or the app's own data folders.
// Read-only; on any problem it adds nothing.
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

// Files that make a folder a project (one is enough).
const MARKERS = [
    '.git', 'package.json', 'deno.json', 'deno.jsonc', 'pyproject.toml', 'setup.py', 'requirements.txt', 'Pipfile',
    'Cargo.toml', 'go.mod', 'Makefile', 'Gemfile', 'composer.json', 'pom.xml', 'build.gradle', 'build.gradle.kts',
    'Package.swift', 'mix.exs', 'pubspec.yaml', 'CMakeLists.txt',
];
const MARKER_EXT = /\.(sln|csproj|fsproj|xcodeproj)$/i;

