// Why a folder is not a place for AGENTS.md, or '' when it is.
export function notAProject(cwd, { home = os.homedir(), env = process.env, tmp = os.tmpdir() } = {}) {
    if (!cwd) return 'no folder';
    const dir = real(cwd);
    const h = real(home);
    if (dir === path.parse(dir).root) return 'disk root';
    if (inside(h, dir)) return 'home folder';
    for (const n of ['Desktop', 'Documents', 'Downloads']) if (dir === path.join(h, n)) return 'home sub-folder';
    if (inside(dir, path.join(h, 'Library'))) return 'Library';
