    // copies of a project (worktrees) are real projects.
    const data = [env.AIB_DATA_DIR, path.join(h, '.ai-builder'), path.join(h, '.ai-builder-classic'), path.join(h, '.claude')].filter(Boolean).map(real);
    for (const d of data) if (inside(dir, d) && !inside(dir, path.join(d, 'worktrees'))) return 'app data folder';
    if (env.AIB_AGENTS_MD_ALLOW_TEMP !== '1') {
        const temps = [tmp, '/tmp', '/private/tmp', '/var/tmp', '/private/var/tmp', '/var/folders', '/private/var/folders'].map(real);
        if (temps.some((t) => inside(dir, t))) return 'temporary folder';
