export function agentsMdNudge(cwd, { source, home, env = process.env, tmp } = {}) {
    // Only when a context starts fresh: a resume or a compaction already had the note.
    if (source === 'resume' || source === 'compact') return '';
    if (notAProject(cwd, { home, env, tmp })) return '';
    if (nearestAgentsMd(cwd, { home })) return '';
    const claude = has(real(cwd), 'CLAUDE.md');
    return [
        'This project has no AGENTS.md — the shared instructions file other AI coding tools (Codex, Cursor, VS Code, Kiro, Gemini CLI…) read, so work done here carries over to them.',
        'As part of your first task in this folder, create it with the agents-md skill: only what you verify in the repo (stack, the real commands from its manifests, folder layout, visible conventions), unknowns marked as unknown, nothing invented, short.',
        claude ? 'This project has a CLAUDE.md: leave it exactly as it is; AGENTS.md gets the tool-neutral facts only.' : '',
