// Branch guard — the agent must act on EXACTLY the branches the person named.
// Seen: asked to merge into "all-staging", it merged into "staging"; it talked about an
// "llm-gateway" branch that doesn't exist. Before a git command that changes branches
// (merge, push, rebase, reset, cherry-pick, checkout/switch, branch -d/-D/-m, worktree),
// this checks every branch involved — including the DESTINATION (the branch checked out
// when merging) — against (1) the repo's real branches and (2) the branch names the
// person wrote in their recent messages. It blocks:
//   - a branch that doesn't exist (no invented names);
//   - a NEAR-MISS of a branch the person named (staging vs all-staging, fix-acf vs
//     fix-acf-2, same last segment in another folder) — the classic mix-up.
// Pure helpers are exported for tests; checkGitBranches() does the I/O.
import fs from 'node:fs';
import { spawnSync } from 'node:child_process';

const REF_OPS = /^(merge|push|rebase|reset|cherry-pick|checkout|switch|branch|pull)$/;
// Options whose VALUE is not a ref (a commit message, a strategy…) — skipped with it.
const VALUE_OPTS = new Set(['-m', '-F', '-X', '-s', '-S', '--message', '--file', '--strategy', '--strategy-option', '--gpg-sign', '-c', '-C', '--exec', '--push-option', '-o']);

export function lastSeg(b) { return String(b).split('/').pop(); }
function lev(a, b) {
    if (Math.abs(a.length - b.length) > 2) return 3;
    const d = Array.from({ length: a.length + 1 }, (_, i) => [i, ...Array(b.length).fill(0)]);
    for (let j = 1; j <= b.length; j++) d[0][j] = j;
    for (let i = 1; i <= a.length; i++) for (let j = 1; j <= b.length; j++) {
        d[i][j] = Math.min(d[i - 1][j] + 1, d[i][j - 1] + 1, d[i - 1][j - 1] + (a[i - 1] === b[j - 1] ? 0 : 1));
    }
    return d[a.length][b.length];
}
// Two DIFFERENT branch names a person could mean one for the other.
export function nearMiss(a, b) {
    if (!a || !b || a === b) return false;
    const la = lastSeg(a).toLowerCase(), lb = lastSeg(b).toLowerCase();
    if (la === lb) return true;                               // same name, other folder
    if (la.length >= 4 && lb.length >= 4 && (la.includes(lb) || lb.includes(la))) return true; // staging ⊂ all-staging
    return lev(la, lb) <= 2 && Math.min(la.length, lb.length) >= 5;
}

// Branch names the person wrote, resolved against the repo's branches: a token counts when
// it IS a branch, or is the last segment of exactly one branch ("fix-acf" →
// "seo-dev-sprint-12/fix-acf"). → { named: Set<full branch>, unmatched: [tokens that look
// like branch names but match none], ambiguous: [{ token, options }] }.
export function namedBranches(text, branches) {
    const all = [...new Set(branches)];
    const named = new Set();
    const unmatched = [];
    const ambiguous = [];
    const tokens = String(text || '').match(/[A-Za-z0-9][A-Za-z0-9._\/-]*[A-Za-z0-9]/g) || [];
    for (const t of new Set(tokens)) {
        if (all.includes(t)) { named.add(t); continue; }
        const bySeg = all.filter((b) => lastSeg(b) === t || b.endsWith('/' + t));
        if (bySeg.length === 1) { named.add(bySeg[0]); continue; }
        if (bySeg.length > 1) { ambiguous.push({ token: t, options: bySeg }); continue; }
        if (/[-/]/.test(t) && /[a-z]/i.test(t) && !/^https?:|\.(com|io|net|org|js|ts|php|json|md|html|css)$/i.test(t) && t.length <= 80) unmatched.push(t);
