}

// Branches a shell command acts on, per segment: [{ op, branches: [...], dest? }].
// `dest` is the branch that receives a merge / cherry-pick / rebase / reset — the one
// checked out at that point (tracked through checkout/switch earlier in the command).
export function refsInCommand(cmd, currentBranch, isBranch) {
    const out = [];
