    for (const seg of String(cmd || '').split(/&&|\|\||;|\n/)) {
        const toks = (seg.trim().match(/"[^"]*"|'[^']*'|\S+/g) || []).map((t) => t.replace(/^['"]|['"]$/g, ''));
