            if (VALUE_OPTS.has(a)) { k++; continue; }    // skip the option and its value
            if (a.startsWith('-')) continue;
            args.push(a);
        }
        // Tags (refs/tags/x) are not branches: a tag push is never a branch mix-up.
        const refs = args.filter((a) => !/^refs\/tags\//.test(a)).map((a) => a.replace(/^origin\//, '').replace(/^refs\/heads\//, '').replace(/[~^].*$/, '').split(':').pop()).filter(Boolean);
