        const involved = [...e.branches, ...(e.dest ? [e.dest] : [])];
        for (const b of (/^(checkout|switch)$/.test(e.op) ? [] : e.branches)) { // checkout also takes file paths
            if (!isBranch(b) && /[a-z]/i.test(b) && !/^[0-9a-f]{7,40}$/i.test(b) && b !== 'HEAD' && !/^(origin|upstream)$/.test(b)) {
                return `git ${e.op}: there is no branch "${b}" in this repo. Use the exact name from \`git branch -a\` — never a guessed or shortened one.`;
            }
        }
        if (!named.size) continue;
        for (const b of involved) {
            if (named.has(b)) continue;
            const meant = [...named].find((n) => nearMiss(b, n));
            if (meant) {
                return `git ${e.op}${b === e.dest ? ` into "${b}" (the checked-out branch)` : ` on "${b}"`}: the person named "${meant}", not "${b}". These are DIFFERENT branches. Use "${meant}" exactly — or, if "${b}" is really intended, ask the person first.`;
            }
        }
    }
    return '';
}

function git(cwd, args) {
    const r = spawnSync('git', args, { cwd, encoding: 'utf8', timeout: 4000 });
    return r.status === 0 ? String(r.stdout || '') : null;
}
// The person's recent messages (newest 6), from the session transcript the hook is given.
// Lines the app adds in brackets ("[Reply style …]", "[If this …]") are not the person's.
export function recentPersonText(transcriptPath, max = 6) {
    try {
        const size = fs.statSync(transcriptPath).size;
        const fd = fs.openSync(transcriptPath, 'r');
        const len = Math.min(size, 4 * 1024 * 1024);
        const buf = Buffer.alloc(len);
        fs.readSync(fd, buf, 0, len, size - len);
        fs.closeSync(fd);
        const texts = [];
        for (const line of buf.toString('utf8').split('\n').reverse()) {
            if (texts.length >= max) break;
            if (!line.includes('"type":"user"')) continue;
            let r; try { r = JSON.parse(line); } catch { continue; }
            if (r.type !== 'user' || r.isSidechain || r.isMeta) continue;
            const c = r.message && r.message.content;
            const t = typeof c === 'string' ? c : Array.isArray(c) ? c.filter((b) => b && b.type === 'text').map((b) => b.text).join('\n') : '';
            if (!t || /^<(task-notification|command-|local-command)/.test(t.trim()) || /^\[Automatic /.test(t.trim())) continue;
            texts.push(t.split('\n').filter((l) => !/^\s*\[[^\]]{20,}\]\s*$/.test(l)).join('\n'));
        }
        return texts.join('\n');
    } catch { return ''; }
}

// The hook's entry: → '' or the block reason.
export function checkGitBranches(data) {
    if (!data || data.tool_name !== 'Bash') return '';
    const cmd = String((data.tool_input && data.tool_input.command) || '');
    if (!/\bgit\b/.test(cmd) || !/\b(merge|push|rebase|reset|cherry-pick|checkout|switch|branch|pull)\b/.test(cmd)) return '';
    const cdm = /(?:^|&&|;)\s*cd\s+("[^"]+"|'[^']+'|\S+)/.exec(cmd);
    const cwd = cdm ? cdm[1].replace(/^['"]|['"]$/g, '') : (data.cwd || process.cwd());
    const list = git(cwd, ['for-each-ref', '--format=%(refname:short)', 'refs/heads', 'refs/remotes']);
    if (list === null) return ''; // not a repo (or git unavailable) — nothing to check against
    const branches = [...new Set(list.split('\n').map((s) => s.trim().replace(/^origin\//, '')).filter((b) => b && b !== 'HEAD' && b !== 'origin'))];
    // An existing tag is a valid ref to push or reset to, not a guessed branch name.
    const tags = new Set((git(cwd, ['tag', '-l']) || '').split('\n').map((s) => s.trim()).filter(Boolean));
    const isBranch = (b) => branches.includes(b) || tags.has(b);
    const current = (git(cwd, ['rev-parse', '--abbrev-ref', 'HEAD']) || '').trim();
    const entries = refsInCommand(cmd, current === 'HEAD' ? '' : current, isBranch);
    if (!entries.length) return '';
    const { named } = namedBranches(recentPersonText(data.transcript_path || ''), branches);
    return judge(entries, named, isBranch);
}

