// Brief Gate — no workflow agent or subagent launches without a real brief.
//
// Fires on PreToolUse for Workflow and Agent/Task. Half of all workflow runs were ending
// NO-GO in design — an unmeasured blocker, a missing input, an unsettled fork — because
// agents were launched on thin briefs. This reads every agent's prompt and holds the
// launch (exit 2 + a message on stderr that says exactly what is missing) unless each one
// states, under its own label:
//   Goal · Why · Inputs · Done when · Out of scope · Budget · Risks · Return
// (Explore / search-only subagents need only Goal + Return; web-fetch page readers need none.) On any parse problem it
// ALLOWS — a broken hook must never block work. A script can opt one agent out with a
// `// brief-gate: skip — <reason>` comment (tiny mechanical steps). It also reads the content:
// Done when needs something measurable and a baseline, and absolute Inputs paths must exist;
// thinner gaps (no success sheet, no stop rule, no DOI step, no blast radius) are advice only.
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { reviewsDir } from './review-gate.mjs';
import { gateLaunch } from './cpu-gate.mjs';

export const SECTIONS = [
    { key: 'goal', label: 'Goal', re: /\b(goal|objective|problem)\s*[:—–-]/i },
    // The why behind the goal: when the plan meets reality, the agent adapts to the intent.
    { key: 'why', label: 'Why', re: /\b(why|intent|purpose)\s*[:—–-]|\b(because|so that|in order to)\b/i },
    { key: 'inputs', label: 'Inputs', re: /\b(inputs?|context|given|sources?|files?)\s*[:—–-]/i },
    { key: 'done', label: 'Done when', re: /\b(done when|done =|definition of done|acceptance( criteria)?|success (criteria|=)|verify by|it'?s done when)\s*[:—–-]?|\bproof\s*[:—–-]/i },
    { key: 'scope', label: 'Out of scope', re: /\b(out of scope|non-?goals?|do not|don'?t|constraints?|scope)\s*[:—–-]/i },
    { key: 'budget', label: 'Budget', re: /\b(budget|time ?box|time limit|stop (after|if|when)|max(imum)? (\d+|time|turns|minutes))\b/i },
    // What could go wrong, and the fallback — decided before launch, not discovered mid-run.
    { key: 'risks', label: 'Risks', re: /\b(risks?|what could go wrong|fallbacks?|contingenc(y|ies))\s*[:—–-]|\bplan b\b|\bif (it|this|that|the [\w-]+) fails\b/i },
    { key: 'return', label: 'Return', re: /\b(return|report|output|deliverable|respond with|reply with|hand back)\s*[:—–-]/i },
