const LIGHT = new Set(['goal', 'return']);
const LIGHT_AGENTS = /^(explore|statusline-setup|claude-code-guide)$/i;
// Agents that only read a web page and answer about it: the prompt is a URL and a question,
// like a WebFetch call, so there is no brief to judge.
const EXEMPT_AGENTS = /^web-fetch$/i;
const MIN_CHARS = 280; // a real brief is never a one-liner

// Token economy (2026-11-25: small UI fixes were briefed with 90-120 min budgets and full test
// matrices; one scroll fix logged 13M+ tokens). A brief's Budget is capped at 45 minutes unless it
// says why it needs longer on a line of its own: "Long run because: <reason>".
export const BUDGET_CAP_MIN = 45;
export function budgetMinutes(prompt) {
