// code is kept), so `agent(` inside a prompt or a commented-out call is not counted.
// Limit: it is a scanner, not a parser — a regex literal holding a quote can confuse it; an
// agent(...) call inside a loop counts once (a call site, not the number of runs).
export function codeOnly(script) {
