            out += ' '; i = j + 1; continue;
        }
        if (c === '`') { stack.push('tpl'); out += ' '; i += 1; continue; }
        if (typeof top === 'number') {
            if (c === '{') stack[stack.length - 1] = top + 1;
            if (c === '}') { if (top === 1) { stack.pop(); out += ' '; i += 1; continue; } stack[stack.length - 1] = top - 1; }
        }
        out += c; i += 1;
    }
