}
// agent( call sites: not a method (x.agent), not a definition (function agent(…)), not part
// of a longer name (subagent().
export function agentCallSites(script) {
    const code = codeOnly(script);
    let n = 0;
    for (const m of code.matchAll(/(^|[^\w$.])agent\s*\(/g)) {
        const before = code.slice(0, m.index + m[1].length);
        if (/\bfunction\s*$/.test(before)) continue;
