}
export const ROLE_WHY = /\brole why\s*[:—–-]/i;
const CHECK_ROLE = /\b(search\w*|scout\w*|census|explor\w*|check\w*|review\w*|verif\w*|audit\w*|skeptic\w*|blast[- ]radius|qa)\b/i;
const SMALL_MODEL = /\bmodel\s*:\s*[`'"](?:claude-)?(?:sonnet|haiku)/i;
// A role's name for spotting repeats: "census 2", "census-b", `review ${f}` → "census", "review".
const roleKey = (label) => String(label || '').toLowerCase().replace(/\$\{[^}]*\}/g, ' ').replace(/(?:[\s#_-]+(?:[0-9]+|[a-z]))+\s*$/, '').replace(/[0-9]+/g, '').replace(/[\s_-]+/g, ' ').trim();
// What looks heavy in a Workflow script, as short lines (empty when it looks lean, or when the
// script says "Long run because: <reason>"). Never a block.
export function workflowAdvice(script) {
    const src = String(script || '');
    if (/\blong run because\s*[:—–-]/i.test(src)) return [];
    const out = [];
    const n = agentCallSites(src);
    if (n > AGENT_SITE_CAP) out.push(`${n} agents (a lean run has about 3: scout, builder, checker; more than ${AGENT_SITE_CAP} is heavy)`);
    const agents = workflowPrompts(src);
    const seen = new Map();
    for (const a of agents) {
        if (/^agent #\d+$/.test(a.label)) continue;
        const k = roleKey(a.label);
        if (k) seen.set(k, (seen.get(k) || 0) + 1);
    }
    for (const [k, c] of seen) if (c > 1) out.push(`'${k}' appears ${c === 2 ? 'twice' : `${c} times`}: merge them into one agent`);
    const heavyChecks = agents.filter((a) => CHECK_ROLE.test(a.label) && !SMALL_MODEL.test(a.opts));
    if (heavyChecks.length) out.push(`${heavyChecks.length} search/check agent${heavyChecks.length > 1 ? 's' : ''} on the default model (${heavyChecks.slice(0, 4).map((a) => a.label).join(', ')}): pass model: 'sonnet' or 'haiku'`);
    return out;
}
export function adviceMessage(lines) {
    return [
        'Brief gate: launched, but this run looks heavy:',
        ...lines.map((l) => `- ${l}`),
        'Lean shape: one scout (small model), one builder, one checker that does the census, skeptic, audit and blast-radius checks in one pass; research only for a real unknown; pass file paths between agents; give each a turn limit.',
