#!/usr/bin/env node
// Batch the work, check at the end (the person's rule, 2026-11-27). Never stops an agent:
//  - every helper agent starts with the work rule in its prompt: make ALL the changes first,
//    then check once at the end; fix what failed, then re-check;
//  - a re-run of a check with nothing changed since the last one, and runs past the 3rd, get a
//    reminder in the agent's context;
//  - from the 4th run of one kind of check (and every 3 runs after), the person gets a "Check runs"
//    note in Needs you, so they can decide whether to step in. No caps, no blocks.
// Why: one UI agent ran the same slow check 99 times (~26M tokens of re-read context).
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import http from 'node:http';
import crypto from 'node:crypto';
import { execFileSync } from 'node:child_process';

export const CHECK_RUNS = 3;

export const WORK_RULE = '\n\n[Work rule] Make ALL the changes first (every file), then run the checks once at the end. Don\'t run a check after each file or each edit. If something fails, fix everything it showed, then re-check. A failure that also happens on main is not yours: note it and move on.';
export function withWorkRule(input) {
    const p = String((input && input.prompt) || '');
    if (!p || p.includes('[Work rule]')) return null;
    return { ...input, prompt: p + WORK_RULE };
}

// Which kind of check a command runs, or '' when it runs none.
export function checkKind(cmd) {
    const c = String(cmd || '');
    if (/\bcheck-app\.mjs\b/.test(c)) return 'app checks';
    if (/\bnode\s+--test\b/.test(c)) return 'unit tests';
    if (/\b(npm|pnpm|yarn|bun)\s+(run\s+)?(-\S+\s+)*(test|eval)\b/.test(c)) return 'test script';
    if (/\b(npx\s+)?(vitest|jest|mocha)\b|\bplaywright\s+test\b/.test(c)) return 'test runner';
    if (/\b(pytest|cargo\s+test|go\s+test)\b/.test(c)) return 'test runner';
    return '';
}

// Pure, for tests: what the n-th run (1-based) of `kind` gets. Never a block.
//   { context } — a reminder for the agent; { notify } — a note for the person.
export function decide(kind, n, { unchanged = false, max = CHECK_RUNS } = {}) {
    if (!kind || n < 2) return null;
    const out = {};
    if (unchanged) out.context = `Check reminder: nothing changed since the last ${kind} run, so this run will show the same result. Fix everything the last run showed first (all failing checks), then run once.`;
    else if (n > max) out.context = `Check reminder: this is run ${n} of ${kind}. Make all the remaining fixes before the next run, and if the same failure keeps coming back, say so in your report instead of retrying.`;
    else out.context = `Check reminder: run ${n} of ${kind}. Fix EVERYTHING the last run showed (all failing checks, not one) before re-running.`;
    if (n > max && (n - max - 1) % max === 0) out.notify = `A helper agent has run ${kind} ${n} times. It keeps working; open the chat if you want to step in.`;
    return out;
}

// The working tree's fingerprint: the same as at the last run → nothing changed.
export function treePrint(cwd) {
    try {
        const out = execFileSync('git', ['-C', cwd, 'status', '--porcelain=v1', '-uall'], { timeout: 3000 }).toString()
            + execFileSync('git', ['-C', cwd, 'diff', 'HEAD'], { timeout: 3000, maxBuffer: 64 * 1024 * 1024 }).toString();
        return crypto.createHash('sha1').update(out).digest('hex');
    } catch { return ''; }
}

