function stateFile(agentId, dir = path.join(os.tmpdir(), `aib-check-budget-${process.getuid ? process.getuid() : 'u'}`)) {
    try { fs.mkdirSync(dir, { recursive: true, mode: 0o700 }); } catch { /* checked below */ }
    try {
        const st = fs.lstatSync(dir);
