    if (!sid || !token || !base) return Promise.resolve();
    return new Promise((resolve) => {
        const body = JSON.stringify({ text });
        const req = http.request(`${base}/api/agent-note`, { method: 'POST', timeout: 2000, headers: { 'content-type': 'application/json', 'content-length': Buffer.byteLength(body), 'x-aib-session': sid, 'x-aib-preview-token': token } }, (res) => { res.resume(); res.on('end', resolve); });
