async function main() {
    let ev = {};
    try { ev = JSON.parse(fs.readFileSync(0, 'utf8') || '{}'); } catch { return; }
    if (ev.tool_name === 'Agent' || ev.tool_name === 'Task') {
        const updated = withWorkRule(ev.tool_input);
        if (updated) process.stdout.write(JSON.stringify({ hookSpecificOutput: { hookEventName: 'PreToolUse', updatedInput: updated } }));
        return;
    }
    if (!ev.agent_id || ev.tool_name !== 'Bash') return; // only helper agents; your own chat is left alone
    const kind = checkKind(ev.tool_input && ev.tool_input.command);
    if (!kind) return;
    const f = stateFile(ev.agent_id);
    if (!f) return;
    const st = readState(f);
    const n = (st[kind] || 0) + 1;
    const print = treePrint(ev.cwd || process.cwd());
    const d = decide(kind, n, { unchanged: n > 1 && Boolean(print) && st[`${kind}#print`] === print });
    st[kind] = n; st[`${kind}#print`] = print; writeState(f, st);
    if (!d) return;
    if (d.notify) await notifyApp(d.notify);
    if (d.context) process.stdout.write(JSON.stringify({ hookSpecificOutput: { hookEventName: 'PreToolUse', additionalContext: d.context } }));
}

if (import.meta.url === `file://${process.argv[1]}`) main();

