// CPU gate — a new background agent or workflow waits while the computer is overloaded.
//
// One project's chats once ran ~8 Claude processes and dozens of agents at the same time:
// load average ~115 on a 16-core Mac, memory full, 6 GB of swap, and the whole Mac crawled.
// Called from brief-gate's PreToolUse hook (Workflow / Agent / Task), after the brief passed:
// while the machine is over the limit it polls every few seconds (up to MAX_WAIT_MS, then it
// lets the launch go), and says once on stderr that it waits — Claude Code streams a hook's
// output as hook_progress, and Ninja Builder turns that marker into one collapsed chat line.
// It never holds the person's own tools: only Workflow, Task, and Agent launches that run in
// the background (Agent with run_in_background:false is the reply itself waiting on it).
//
// "Keep the computer responsive" (Settings › General › Speed & cost): gentle | balanced | off.
// The app writes the choice to the file in AIB_RESPONSIVE_FILE; no file → balanced.
// Every threshold lives in LEVELS below. On any error it ALLOWS: a broken gate never blocks work.
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { execFileSync } from 'node:child_process';

// load: 1-minute load average above this many times the logical cores = overloaded.
// mem:  free + inactive memory below this share of the total = overloaded (or macOS says
//       memory pressure is critical).
export const LEVELS = {
    gentle: { load: 1.0, mem: 0.15 },
    balanced: { load: 1.5, mem: 0.10 },
    off: null,
};
export const DEFAULT_LEVEL = 'balanced';
export const POLL_MS = 5000;
export const MAX_WAIT_MS = 9 * 60 * 1000; // Claude Code's own hook limit is 10 minutes
export const STAGGER_MS = 10000;          // after a wait, launches leave one at a time
export const MARKER = '[ninja-cpu-wait]';

export function normalizeLevel(v) {
    const s = String(v || '').trim().toLowerCase();
