    // A web-fetch page reader runs in the reply's foreground and is tiny.
    if (t === 'Agent') return !(input && (input.run_in_background === false || /^web-fetch$/i.test(String(input.subagent_type || ''))));
    return false;
}

// Memory still available, as a share of the total (0..1), and macOS's pressure level.
// macOS: free + inactive + speculative pages (os.freemem() counts free pages only, ~0%).
// Linux: MemAvailable. Elsewhere: os.freemem().
export function readMemory({ platform = process.platform, exec = (cmd, args) => execFileSync(cmd, args, { encoding: 'utf8', timeout: 2000 }), readFile = (p) => fs.readFileSync(p, 'utf8') } = {}) {
    const total = os.totalmem();
    try {
        if (platform === 'darwin') {
            const vm = exec('vm_stat', []);
            const page = Number((vm.match(/page size of (\d+)/) || [])[1]) || 4096;
            const pages = (k) => Number((vm.match(new RegExp(`Pages ${k}:\\s+(\\d+)`)) || [])[1]) || 0;
            const avail = (pages('free') + pages('inactive') + pages('speculative')) * page;
