            const kb = (k) => Number((m.match(new RegExp(`^${k}:\\s+(\\d+)`, 'm')) || [])[1]) || 0;
            const t = kb('MemTotal') || total / 1024;
            return { free: kb('MemAvailable') / t, critical: false };
        }
    } catch { /* fall back */ }
    return { free: os.freemem() / total, critical: false };
}

// → { over: bool, why: '' | text, load, cores, limit, free }
export function overloaded(level, { loadavg = os.loadavg(), cores = os.cpus().length || 1, memory = null } = {}) {
    const lv = LEVELS[normalizeLevel(level)];
    if (!lv) return { over: false, why: '' };
    const load = Number(loadavg && loadavg[0]) || 0;
    const limit = Math.max(1, Math.round(cores * lv.load * 10) / 10);
    const mem = memory || readMemory();
    const why = [];
    if (load > limit) why.push(`load ${load.toFixed(0)} on ${cores} cores (limit ${limit})`);
    if (mem.critical) why.push('memory pressure is critical');
    else if (mem.free < lv.mem) why.push(`${Math.round(mem.free * 100)}% memory free (limit ${Math.round(lv.mem * 100)}%)`);
    return { over: why.length > 0, why: why.join(' · '), load, cores, limit, free: mem.free };
