function markRelease(file, at) { try { fs.writeFileSync(file, JSON.stringify({ at })); } catch { /* best-effort */ } }

// The wait. Every dependency can be swapped in tests. → { waited: ms, outcome: 'free' | 'room' | 'timeout' }
export async function waitForRoom({
    level = readLevel(),
    check = (lv) => overloaded(lv),
    sleep = (ms) => new Promise((r) => setTimeout(r, ms)),
    now = () => Date.now(),
    notify = (text) => process.stderr.write(text + '\n'),
    pollMs = POLL_MS,
    maxWaitMs = MAX_WAIT_MS,
    staggerMs = STAGGER_MS,
    stagger = staggerFile(),
} = {}) {
    if (!LEVELS[normalizeLevel(level)]) return { waited: 0, outcome: 'free' };
    const start = now();
    let st = check(level);
    if (!st.over) return { waited: 0, outcome: 'free' };
    notify(`${MARKER} ${JSON.stringify({ why: st.why, maxMin: Math.round(maxWaitMs / 60000) })}`);
    for (;;) {
        if (now() - start >= maxWaitMs) {
            notify(`${MARKER} ${JSON.stringify({ done: 'timeout', waitedS: Math.round((now() - start) / 1000) })}`);
            return { waited: now() - start, outcome: 'timeout' };
        }
        await sleep(pollMs);
        st = check(level);
        if (!st.over && now() - lastRelease(stagger) >= staggerMs) {
            markRelease(stagger, now());
            notify(`${MARKER} ${JSON.stringify({ done: 'room', waitedS: Math.round((now() - start) / 1000) })}`);
            return { waited: now() - start, outcome: 'room' };
        }
    }
}

// Called by brief-gate's main once the launch is otherwise allowed.
export async function gateLaunch(ev, opts = {}) {
    try {
        if (!ev || !gated(ev.tool_name, ev.tool_input || {})) return { waited: 0, outcome: 'free' };
        return await waitForRoom(opts);
    } catch { return { waited: 0, outcome: 'free' }; }
}

