// Army discipline, enforced (not just described). Two hook events:
//
//  UserPromptSubmit — every message: the saved lessons that match THIS task (project +
//    global memory, ranked by rarity-weighted word overlap) go into the turn's context,
//    each whole and once per context (the before-action check itself is in the system
//    prompt + the app's one-line reminder). A message that reports a failure — the person saying it's
//    wrong / not fixed / broken, or the app's report of a FAILED or NO-GO workflow — opens
//    a required after-action review for this chat.
//  Stop — while a review is open, the turn can't end until the lesson is saved
//    (memory_save tagged lesson/aar, or a review file in the review folder, see aarDir). Held at most twice,
//    then it lets go and says so — a gate must never trap the chat.
// On any problem it allows and adds nothing.
import crypto from 'node:crypto';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { isLessonSeen, markLessonsSeen, memoryFiles, seenLessons } from './lessons.mjs';

const MAX_HOLDS = 2;
const STOP = new Set('the a an and or but to of in on for is are was were be it this that with as at by from i we you my our me your not no do does did can could should would will just so if then than when what why how its it\'s all any some more now again still also please yes okay done get got make see look want need use one two'.split(' '));
const words = (t) => String(t || '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').split(' ').filter((w) => w.length > 2 && !STOP.has(w));

// No phrase list decides what a failure is: Claude judges each message itself (the prompt
// note below asks it to). Only two explicit signals open a review on their own: the app's
// workflow report saying "It FAILED.", and the person typing /aar.
const REPORT_FAIL_RE = /^\s*\[Automatic report[^\]]*\][^\n]*\bIt FAILED\./;

// The person's own words only: the app appends notes to every message (the reply-style
// setting — "…caveats I didn't ask for" —, memory reminders, attached-file lists, reply
// quotes, branch notes). Read as the person's, they flagged EVERY message as a failure.
export function personText(prompt) {
    return String(prompt || '')
        .replace(/(^|\n)\[(?!Automatic)[^\n]*?(?:\n(?!\n)[^\n]*?)*\](?=\s*(\n|$))/g, '\n')
        .replace(/(^|\n)Attached files \([^\n]*\n(?:- [^\n]*\n?)*/g, '\n')
