}
export function reportsFailure(prompt) {
    const raw = String(prompt || '');
    if (REPORT_FAIL_RE.test(raw)) return true;
    return /^\s*\/aar\b/.test(personText(raw));
}

function readLessons(file) {
    let raw = '';
    try { raw = fs.readFileSync(file, 'utf8'); } catch { return []; }
    const recs = [];
    const dead = new Set();
    for (const line of raw.split('\n')) {
        try { const r = JSON.parse(line); if (!r || typeof r.id !== 'string') continue; if (r.deleted === true) dead.add(r.id); else recs.push(r); } catch { /* skip */ }
    }
