    const sets = lessons.map((r) => termSet(`${r.text} ${(r.tags || []).filter((t) => !/^(lesson|aar)$/i.test(String(t))).join(' ')}`));
    const df = new Map();
    for (const s of sets) for (const w of s) df.set(w, (df.get(w) || 0) + 1);
    const N = lessons.length;
    const idf = (w) => Math.log(1 + N / (df.get(w) || 0.5));
