        let dot = 0;
        let hits = 0;
        let ln = 0;
        for (const w of sets[i]) { const v = idf(w) ** 2; ln += v; if (q.has(w)) { dot += v; hits++; } }
        return { r, hits, score: ln && qn ? dot / Math.sqrt(qn * ln) : 0 };
