}
// Lessons that match the task, best first.
export function relevantLessons(prompt, root, home, limit = 4) {
    const f = memoryFiles(root, home);
    const all = [...readLessons(f.project).map((r) => ({ ...r, where: 'project' })), ...readLessons(f.global).map((r) => ({ ...r, where: 'global' }))];
    return scoreLessons(prompt, all)
        .filter((x) => x.score >= MATCH_MIN && x.hits >= MATCH_MIN_HITS)
        .sort((a, b) => b.score - a.score)
        .slice(0, limit)
        .map((x) => x.r);
}

const stateDir = () => path.join(os.tmpdir(), 'ninja-discipline');
const stateFile = (sid) => path.join(stateDir(), `${crypto.createHash('sha1').update(String(sid || 'none')).digest('hex').slice(0, 16)}.json`);
export function openReview(sid, prompt, now = Date.now()) {
    fs.mkdirSync(stateDir(), { recursive: true });
    // A review already open (last 30 min) keeps its hold count: re-opening it must never
    // reset the cap — that let one misread message hold a chat over and over.
    const cur = readReview(sid);
    const holds = cur && now - cur.at < 30 * 60 * 1000 ? cur.holds : 0;
    fs.writeFileSync(stateFile(sid), JSON.stringify({ at: cur && holds ? cur.at : now, holds, explicit: true, what: String(prompt || '').slice(0, 200) }));
}
// Every other message: remember when this turn began (to find Claude's own review in it).
export function noteTurn(sid, now = Date.now()) {
    try {
        fs.mkdirSync(stateDir(), { recursive: true });
        fs.writeFileSync(stateFile(sid), JSON.stringify({ at: now, holds: 0, explicit: false }));
    } catch { /* best effort */ }
}
// The transcript entries written since `since` — read from the END of the file, a chunk at a
// time, stopping at the first older entry. Reading the whole transcript took 22 s on a long
// chat (356 MB) and held the end of EVERY reply that long.
export function entriesSince(transcriptPath, since) {
    let fd;
    try { fd = fs.openSync(transcriptPath, 'r'); } catch { return []; }
    const out = [];
    try {
        const size = fs.fstatSync(fd).size;
        const CHUNK = 1 << 20;
        let pos = size;
        let tail = '';
        let done = false;
        while (pos > 0 && !done && size - pos < 64 * CHUNK) {
            const len = Math.min(CHUNK, pos);
            pos -= len;
            const buf = Buffer.alloc(len);
            fs.readSync(fd, buf, 0, len, pos);
            const text = buf.toString('utf8') + tail;
            const lines = text.split('\n');
            tail = pos > 0 ? lines.shift() : ''; // a line cut by the chunk start: finish it next round
            for (let i = lines.length - 1; i >= 0; i--) {
