// Did Claude's reply in this turn say it ran an after-action review?
export function declaredReview(transcriptPath, since) {
    for (const e of entriesSince(transcriptPath, since)) {
        if (!e || e.type !== 'assistant') continue;
        const ts = Date.parse(e.timestamp);
        if (Number.isFinite(ts) && ts < since - 1000) continue;
        for (const b of (e.message && Array.isArray(e.message.content) ? e.message.content : [])) {
            if (b && b.type === 'text' && /after-action review\s*:/i.test(String(b.text || ''))) return true;
        }
