}
export function readReview(sid) { try { return JSON.parse(fs.readFileSync(stateFile(sid), 'utf8')); } catch { return null; } }
export function closeReview(sid) { try { fs.rmSync(stateFile(sid), { force: true }); } catch { /* gone */ } }

// Where review files go: the app's notes folder for this project, OUTSIDE the repo
// (AIB_PROJECT_DATA/aar); <project>/.claude/aar only for a chat started without the app.
export function aarDir(root) {
    const data = (process.env.AIB_PROJECT_DATA || '').trim();
    return data ? path.join(data, 'aar') : path.join(root || process.cwd(), '.claude', 'aar');
}
// Was the review done since `since`? A lesson in the app's memory (project or global), a
// review file in the review folder (aarDir), or — from the transcript — a memory_save with
// the lesson tag or a write into a review folder. The memory and the folder are checked first:
// the transcript path the CLI passes can be another file than the one a resumed chat
// writes to, and the gate then kept holding after the lesson was saved.
// A review counts only when its lesson names what enforces it: a promise ("from now on I'll
