            const name = String(b.name || '');
            const input = b.input || {};
            if (/memory_save$/.test(name) && Array.isArray(input.tags) && input.tags.some((t) => /^(lesson|aar)$/i.test(String(t))) && ENFORCED_RE.test(String(input.text || ''))) return true;
            if (/^(Write|Edit|MultiEdit)$/.test(name) && /[\\/](\.claude[\\/])?aar[\\/]/.test(String(input.file_path || '')) && ENFORCED_RE.test(String(input.content || input.new_string || ''))) return true;
        }
    }
    return false;
}

export function onPrompt(ev, { root, home, now = Date.now() } = {}) {
    const prompt = String(ev.prompt || '');
    const parts = [];
    const explicit = reportsFailure(prompt);
    // The app's and Claude Code's own messages (wake-ups, reports, task notifications…) are
    // not the person: no "judge this message" note and no lessons on them.
    const appMsg = /^\s*(\[Automatic|\[Workflow checkpoint|\[System note|<task-notification|Stop hook feedback|Army discipline:)/i.test(prompt);
    if (explicit) {
        openReview(ev.session_id, prompt, now);
        parts.push(`ARMY DISCIPLINE — a failure was reported. Before fixing, run the after-action review (army-discipline skill): planned vs. actual from evidence, the confirmed cause, one change that enforces it — save the lesson with memory_save (tags ["lesson","aar"], scope project, or global when it applies everywhere) and write the review to ${aarDir()}/<YYYY-MM-DD>-<slug>.md (the app's notes folder for this project, outside the repo). The turn cannot end until that is done.`);
    } else {
        // The "judge whether this reports a failure / before-action check" rule is in the
        // chat's system prompt once (src/claude-runner.js DISCIPLINE_INSTRUCTION); on every
        // message it cost ~130 tokens that stayed until compaction.
        noteTurn(ev.session_id, now);
    }
    // Each lesson once per context: one already shown (at session start or with an earlier
    // message) is still there — sending it again only added tokens. Nothing is cut: a lesson
    // goes in whole, once; the rest stay findable with memory_search.
    const seen = seenLessons(ev.session_id);
    const lessons = appMsg && !explicit ? [] : relevantLessons(personText(prompt), root, home).filter((r) => !isLessonSeen(seen, r));
    markLessonsSeen(ev.session_id, lessons);
    if (lessons.length) {
        parts.push('Lessons from earlier reviews that match this task — apply them:\n' + lessons.map((r) => `- ${String(r.text).replace(/\s+/g, ' ').trim()} (${r.where})`).join('\n'));
    }
    return parts.join('\n\n');
}

// → { block: true, reason } | { block: false, note? }
export function onStop(ev, { now = Date.now(), root, home } = {}) {
    let st = readReview(ev.session_id);
    if (!st) return { block: false };
    // Not an explicit report: hold only when Claude itself said it ran a review this turn.
    if (!st.explicit && !declaredReview(ev.transcript_path, st.at)) return { block: false };
    if (reviewDone(ev.transcript_path, st.at, { root: root || ev.cwd, home })) { closeReview(ev.session_id); return { block: false }; }
    if (st.holds >= MAX_HOLDS) { closeReview(ev.session_id); return { block: false }; }
    st.holds += 1;
    try { fs.writeFileSync(stateFile(ev.session_id), JSON.stringify(st)); } catch { /* best effort */ }
    return {
        block: true,
        reason: `Army discipline: an after-action review is due this turn and no lesson is saved yet. Run the after-action review now (army-discipline skill): what was supposed to happen, what actually happened (evidence), the confirmed cause, the one change you made. The lesson must name what enforces it — "Enforced by: <the hook, test or check that now blocks it>", or "No gate: <why none is possible>"; a promise ("from now on I will…") does not count — then memory_save the lesson with tags ["lesson","aar"] (scope project, or global) AND write the review to ${aarDir()}/<YYYY-MM-DD>-<slug>.md (the app's notes folder for this project, outside the repo; if memory_save is not available, the file alone counts — never the CLI auto-memory MEMORY.md). Don't announce the review in the chat; the reply just says the cause and the fix plainly.`,
    };
