function main() {
    let ev = {};
    try { ev = JSON.parse(fs.readFileSync(0, 'utf8') || '{}'); } catch { process.exit(0); }
    try {
        const root = (process.env.AIB_PROJECT_ROOT || '').trim() || ev.cwd || process.cwd();
        if (ev.hook_event_name === 'UserPromptSubmit') {
            const text = onPrompt(ev, { root });
            if (text) process.stdout.write(JSON.stringify({ hookSpecificOutput: { hookEventName: 'UserPromptSubmit', additionalContext: text } }));
            process.exit(0);
        }
        if (ev.hook_event_name === 'Stop' || ev.hook_event_name === 'SubagentStop') {
            if (ev.hook_event_name === 'SubagentStop') process.exit(0);
            const r = onStop(ev, { root });
            if (r.block) { process.stderr.write(r.reason + '\n'); process.exit(2); }
        }
    } catch { /* never block on a hook error */ }
    process.exit(0);
}
if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) main();

