// Done Gate — holds a build open until its Definition of Done is proven.
//
// Fires on Stop. It only acts when the working directory has a
// `.builder/done.md` (i.e. a real, gated build) AND the model is actually
// claiming the build is finished. If the model is just pausing to ask the
// person something, or this isn't a gated build, it stays out of the way.
//
// Blocks via exit code 2 + a message on stderr (the documented Stop-hook way),
// which is fed back so the model keeps working until nothing is pending.
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

// Resolve a build-trail artifact. The app relocates the trail OUT of the project
// to AIB_BUILDER_DIR; prefer that, but fall back to the legacy `<cwd>/.builder`
// (and prefer whichever actually exists) so the gate still fires if the agent
// wrote there out of habit, or when run without the app (env unset).
export function resolveArtifact(cwd, name) {
    const env = (process.env.AIB_BUILDER_DIR || '').trim();
    const candidates = [];
    if (env) candidates.push(path.join(env, name));
    candidates.push(path.join(cwd, '.builder', name));
    for (const c of candidates) if (fs.existsSync(c)) return c;
    return candidates[0];
}

// Verify→repair loop exhaustion: if the Verification log shows the loop ran its
// full 3 rounds and the last verdict still isn't GO, the model should escalate to
// the person, not keep grinding. Redirect the guidance instead of "run /handoff".
export function loopExhausted(text) {
    const m = text.match(/##\s*Verification log[\s\S]*?(?=\n###\s|\n##\s|\n#\s|$)/i);
    if (!m) return false;
    const sect = m[0];
    // Read the verdict per round line ("Round N — VERDICT …"), so free text in the
    // resolved:/open: notes can't be mistaken for the round's verdict.
    let maxRound = 0;
    let last = '';
    for (const r of sect.matchAll(/^\s*(?:-\s*)?round\s*(\d+)\s*[—:-]+\s*(NO-GO|GO-WITH-FIXES|GO)\b/gim)) {
        const n = parseInt(r[1], 10) || 0;
        if (n >= maxRound) {
            maxRound = n;
            last = r[2].toUpperCase();
        }
    }
    return maxRound >= 3 && last && last !== 'GO';
}

// Parse the "## Acceptance checks" section into {checked, text, proof} items.
// A proof: line binds to the checkbox item above it, up to the next checkbox
// or the next heading.
export function parseAcceptance(text) {
    const m = text.match(/##\s*Acceptance checks[\s\S]*?(?=\n##\s|\n#\s|$)/i);
    if (!m) return [];
    const items = [];
    let cur = null;
    for (const line of m[0].split('\n')) {
        const box = line.match(/^\s*-\s*\[( |x|X)\]\s*(.*)$/);
        if (box) {
            cur = { checked: box[1].toLowerCase() === 'x', text: box[2].trim(), proof: '' };
            items.push(cur);
            continue;
        }
        const p = line.match(/^\s*proof:\s*(.*)$/i);
        if (p && cur && !cur.proof) cur.proof = p[1].trim();
    }
    return items;
}

// A proof is weak when it carries no real evidence: empty, still (pending), or an
// obvious placeholder (<...>, TODO, tbd). This is deliberately narrow — it does
// not try to judge the quality of a real proof, only spot the non-proofs.
export function proofIsWeak(proof) {
    const p = String(proof || '').trim();
    if (!p) return true;
    if (/\(pending\)/i.test(p)) return true;
    if (/^<[^>]*>$/.test(p)) return true;
    if (/\b(todo|tbd)\b/i.test(p)) return true;
    return false;
}

// If a proof cites a file under .builder/proofs/, that file must exist — in the
// relocated build-trail dir (AIB_BUILDER_DIR) or the legacy `<cwd>/.builder`.
// Returns the cited path when found in neither, or null when nothing to check.
export function missingProofFile(proof, cwd) {
    const m = String(proof || '').match(/\.builder\/(proofs\/[^\s)]+)/);
    if (!m) return null;
    const rel = m[1];
    const env = (process.env.AIB_BUILDER_DIR || '').trim();
    const bases = [];
    if (env) bases.push(env);
    bases.push(path.join(cwd, '.builder'));
    for (const b of bases) if (fs.existsSync(path.join(b, rel))) return null;
    return m[0];
}

// The new enforcement: every CHECKED acceptance item must carry real captured
// evidence. Returns one {text, reason} per offending checked item.
export function proofIssues(done, cwd) {
    const issues = [];
    for (const it of parseAcceptance(done)) {
        if (!it.checked) continue;
        if (proofIsWeak(it.proof)) {
            issues.push({ text: it.text, reason: 'no real proof captured' });
            continue;
        }
        const missing = missingProofFile(it.proof, cwd);
        if (missing) issues.push({ text: it.text, reason: `proof file not found: ${missing}` });
    }
    return issues;
}

function main() {
    const allow = () => process.exit(0);

    let raw = '';
    try {
        raw = fs.readFileSync(0, 'utf8');
    } catch {
        allow();
    }

    let data = {};
    try {
        data = JSON.parse(raw || '{}');
    } catch {
        allow();
    }

    // Loop guard: never block twice in a row (prevents an infinite stop loop).
    if (data.stop_hook_active === true) allow();

    const cwd = typeof data.cwd === 'string' && data.cwd ? data.cwd : process.cwd();
    const donePath = resolveArtifact(cwd, 'done.md');

    // No Definition of Done here → not a gated build (a doc, a plan, a chat). Leave it alone.
    if (!fs.existsSync(donePath)) allow();

    // Only enforce when the model is asserting completion. A turn that pauses to
    // ask the person a question must be allowed to stop, or the human loop breaks.
    const message = String(data.last_assistant_message || '');
    const claimsDone =
        /\b(done|finished|complete|completed|ready to (hand|ship|deploy|go|launch)|handed off|all set|build is (done|ready|complete|finished)|shipped it)\b/i.test(
            message
        );
    if (!claimsDone) allow();

    let done = '';
    try {
        done = fs.readFileSync(donePath, 'utf8');
    } catch {
        allow();
    }

    const unchecked = (done.match(/^\s*-\s*\[ \]\s*(.+)$/gm) || []).map((l) =>
        l.replace(/^\s*-\s*\[ \]\s*/, '').trim()
    );
    const pending = (done.match(/\(pending\)/gi) || []).length;
    const journalMissing = !fs.existsSync(resolveArtifact(cwd, 'journal.md'));
    const proofProblems = proofIssues(done, cwd);

    if (unchecked.length === 0 && pending === 0 && !journalMissing && proofProblems.length === 0) allow();

    const exhausted = loopExhausted(done);

    const out = [];
    out.push('HOLD — this build is not done: .builder/done.md still has open items, so do not call it finished yet.');
    if (unchecked.length) {
        out.push(`Unchecked (${unchecked.length}):`);
        for (const item of unchecked.slice(0, 12)) out.push(`  - ${item}`);
        if (unchecked.length > 12) out.push(`  ...and ${unchecked.length - 12} more`);
    }
    if (pending) out.push(`Proof/verdict still marked (pending): ${pending}.`);
    if (proofProblems.length) {
        out.push(`Checked items without real proof (${proofProblems.length}):`);
        for (const p of proofProblems.slice(0, 12)) out.push(`  - ${p.text} — ${p.reason}`);
        if (proofProblems.length > 12) out.push(`  ...and ${proofProblems.length - 12} more`);
    }
    if (journalMissing) out.push(`No .builder/journal.md yet — start it from ${process.env.CLAUDE_PLUGIN_ROOT ? path.join(process.env.CLAUDE_PLUGIN_ROOT, 'templates', 'journal.md') : 'templates/journal.md'}.`);
    if (exhausted) {
        out.push(
            'The verify → repair loop hit its 3-round limit without a clean pass. Do NOT report this as done. Instead, tell the person in plain language what is still open (see the Verification log in .builder/done.md) and hand those decisions to them.'
        );
    } else {
        out.push(
            'For each item capture a real Proof (a command and its output, a passing test, or a file under .builder/proofs/), run /handoff to fill the proofs and get an independent Second Look (skeptic) GO, then check the boxes. Claim done only when every checked item carries real proof and nothing is unchecked or (pending).'
        );
    }

    process.stderr.write(out.join('\n') + '\n');
    process.exit(2);
}

let directRun = true;
try {
    directRun = process.argv[1]
        ? fs.realpathSync(path.resolve(process.argv[1])) === fs.realpathSync(fileURLToPath(import.meta.url))
        : true;
} catch {
    directRun = true;
}
if (directRun) main();

