// Job Guard — an agent never stops, restarts or re-tunes work running on a server on its own.
//
// Fires on PreToolUse for Bash and ssh tools. An agent killed and restarted its own server
// runs, its requeue script killed another test job, and it changed the server's slot count
// four times (zoe-agi, 2026-11-02); its after-action review promised "I don't touch running
// server jobs", a promise nothing enforced. This holds (exit 2 + why on stderr):
//  - a command on another machine (ssh, or an ssh tool) that kills, stops or restarts
//    processes or services, and job-scheduler cancels anywhere (scancel, qdel);
//  - a second change to the same file on another machine in one chat (a setting tuned
//    again and again instead of decided once).
//  - a background wait loop (`until …; do sleep …; done`) with no way out but its success
//    line: when the run it watches crashes, it waits forever (one ran 6h+, 2026-11-07).
//    It must also stop when the run exits (kill -0 / pgrep) or after a limit (timeout,
//    alarm, SECONDS, a counter).
// Unless the person's own latest message asks for it (stop, kill, cancel, restart…).
// On any parse problem it ALLOWS: a broken hook must never block work.
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { entriesSince, personText } from './discipline.mjs';
import { longRunPatterns } from './review-gate.mjs';

const REMOTE = /\bssh\b/;
const STOPS = /(^|[\s;&|(`'"])(pkill|killall|kill(?!\s+-0\b))\b|\bsystemctl\s+(stop|restart|kill|reload)\b|\bservice\s+\S+\s+(stop|restart)\b|\bdocker\s+(stop|kill|restart|rm\s+-f)\b|\btmux\s+kill-|\bscreen\s+-\S*X\S*\s+quit\b|\bpm2\s+(stop|restart|delete|kill)\b|\bsupervisorctl\s+(stop|restart)\b/;
const SCHEDULER = /(^|[\s;&|(])(scancel|qdel|bkill)\b/;

const WAIT_LOOP = /\b(until|while)\b[\s\S]*?\bdo\b[\s\S]*?\bsleep\b/;
const WAIT_EXIT = /\btimeout\s|\bgtimeout\b|kill\s+-0\b|\bpgrep\b|\balarm\b|\bSECONDS\b|\$\(\(|\(\(\s*\w+\s*(\+\+|\+=|--|-=)|\bfor\s+\w+\s+in\b|\bbreak\b/;
// A background wait loop that can only end on its success line.
export function endlessWaiter(toolName, input) {
    if (String(toolName || '') !== 'Bash' || !input || input.run_in_background !== true) return false;
    const cmd = String(input.command || '');
    return WAIT_LOOP.test(cmd) && !WAIT_EXIT.test(cmd);
}

// The command a tool call runs, for Bash and for ssh tools (their input carries `command`).
export function commandOf(toolName, input) {
    const name = String(toolName || '');
    const cmd = String((input && (input.command || input.cmd)) || '');
    if (name === 'Bash') return { cmd, remote: REMOTE.test(cmd) };
    if (/ssh/i.test(name)) return { cmd, remote: true };
    return { cmd: '', remote: false };
}
// Also here: killing a long run by name (`pkill -f land_verified.sh`), the project's own
// long-run patterns or a test runner.
export function stopsJobs(toolName, input, patterns = longRunPatterns()) {
    const { cmd, remote } = commandOf(toolName, input);
    if (!cmd) return false;
    if (SCHEDULER.test(cmd)) return true;
    if (remote) return STOPS.test(cmd);
    for (const m of cmd.matchAll(/\b(pkill|killall)\b([^;&|\n]*)/g)) {
        const target = m[2];
        if (/\b(cargo|pytest|rustc|nextest|jest|vitest|gradle|mvn)\b/.test(target) || patterns.some((re) => re.test(target))) return true;
    }
    return false;
}
// Files a command writes on another machine: `tee [-a] <path>`, `> <path>`, `sed -i … <path>`.
export function remoteWrites(toolName, input) {
    const { cmd, remote } = commandOf(toolName, input);
    if (!remote || !cmd) return [];
    const out = new Set();
    for (const m of cmd.matchAll(/\btee\s+(?:-a\s+)?([~/][^\s;'"|&)]+)/g)) out.add(m[1]);
    for (const m of cmd.matchAll(/(?:^|[^>2&])>{1,2}\s*([~/][^\s;'"|&)]+)/g)) if (!/^\/(dev|tmp|proc)\//.test(m[1])) out.add(m[1]);
    for (const m of cmd.matchAll(/\bsed\s+-i\S*\s+(?:'[^']*'|"[^"]*"|\S+)\s+([~/][^\s;'"|&)]+)/g)) out.add(m[1]);
    return [...out];
}

// Does the person's latest message (not the app's or Claude Code's) ask to stop or restart?
const APP_MSG = /^\s*(\[Automatic|\[Workflow checkpoint|\[System note|<task-notification|Stop hook feedback|Army discipline:|\[Request interrupted)/i;
export const ASKS_STOP = /\b(stop|kill|cancel|abort|restart|re-?start|reload|requeue|re-?queue|terminate|shut\s*down)\b/i;
// A short yes (typos included) to the agent's own question that named the action counts as asking.
const AFFIRM = /^\s*(y(es|ep|eah?|up)?|tes|yse|ok(ay)?|k|sure|go( ahead)?|do it|approved?|confirm(ed)?|yes,? (please|go ahead|do it))\s*[.!]*\s*$/i;
export const ASKS_CHANGE = /\b(change|set|tune|raise|lower|increase|decrease|bump|switch)\b/i;
// A message the person sent while the agent was working reaches it inside a tool result
// ("The user sent a new message while you were working: …"); the transcript keeps it only in
// the request record, so read it from there too — it is the person's own latest message.
// Only the harness's exact wrapper counts: the block starts with it and ends with its closing line.
const STEER_RE = /^The user sent a new message while you were working:\n([\s\S]*?)\n\n[\s\S]*This is how Claude Code surfaces messages the user sends mid-turn[^\n]*\s*$/;
function steeredText(e) {
    const m = e.message;
    if (!m || (m.role && m.role !== 'user') || !Array.isArray(m.content)) return '';
    for (let k = m.content.length - 1; k >= 0; k--) {
        const b = m.content[k];
        const hit = b && b.type === 'text' && typeof b.text === 'string' && !b.text.includes('<system-reminder>') ? STEER_RE.exec(b.text) : null;
        if (hit && hit[1].trim()) return hit[1].replace(/\n\n\[The person sent this[\s\S]*$/, '').trim();
    }
    return '';
}
export function personAsked(transcriptPath, now = Date.now(), wants = ASKS_STOP) {
    const entries = entriesSince(transcriptPath, now - 12 * 3600 * 1000);
    for (let i = entries.length - 1; i >= 0; i--) {
        const e = entries[i];
        if (!e || e.isMeta || e.isCompactSummary || e.isSidechain) continue;
        const steer = e.type === 'api-request-blob' || e.type === 'user' ? steeredText(e) : '';
        if (!steer && e.type !== 'user') continue;
        const c = e.message && e.message.content;
        const text = steer || (typeof c === 'string' ? c : Array.isArray(c) ? c.filter((b) => b && b.type === 'text').map((b) => b.text).join('\n') : '');
        if (!text.trim() || APP_MSG.test(text)) continue;
        const said = personText(text);
        if (wants.test(said)) return true;
        if (!AFFIRM.test(said)) return false;
        // A yes: did the agent's last message before it ask about exactly this kind of action?
        for (let j = i - 1; j >= 0; j--) {
            const a = entries[j];
            if (!a || a.isSidechain) continue;
            if (a.type === 'user') {
                const uc = a.message && a.message.content;
                if (typeof uc === 'string' || (Array.isArray(uc) && uc.some((b) => b && b.type === 'text'))) return false; // an earlier person message: no question in between
                continue;
            }
            if (a.type !== 'assistant') continue;
            const ac = a.message && a.message.content;
            const said2 = Array.isArray(ac) ? ac.filter((b) => b && b.type === 'text').map((b) => b.text).join('\n') : '';
            if (!said2.trim()) continue;
            return /\?/.test(said2) && wants.test(said2);
        }
        return false;
    }
    return false;
}

const stateDir = () => path.join(os.tmpdir(), 'aib-job-guard');
function seenWrites(sid) { try { return JSON.parse(fs.readFileSync(path.join(stateDir(), `${sid}.json`), 'utf8')); } catch { return {}; } }
function saveWrites(sid, map) {
    try { fs.mkdirSync(stateDir(), { recursive: true }); fs.writeFileSync(path.join(stateDir(), `${sid}.json`), JSON.stringify(map)); } catch { /* best effort */ }
}

// → '' (allow) or the reason it is held.
export function judge(ev, { now = Date.now(), asked = personAsked } = {}) {
    const input = ev.tool_input || {};
    if (stopsJobs(ev.tool_name, input)) {
        if (asked(ev.transcript_path, now, ASKS_STOP)) return '';
        return 'Job guard: not run. This stops, kills or restarts work running on a server, and the person did not ask for that. '
            + 'Running jobs are theirs: a killed test run costs a full re-run, and killing one job can take down another. '
            + 'Ask the person first, saying which job and why. Never work around this with a script that does the same.';
    }
    if (endlessWaiter(ev.tool_name, input)) {
        return 'Job guard: not run. This background wait loop only ends when its success line appears; if the run it watches '
            + 'crashes, it waits forever (one ran 6h+). Also end it when that run exits (`while kill -0 $PID` / pgrep) '
            + 'or after a limit (`timeout 3600 …`, a counter, SECONDS), and match failure lines too.';
    }
    const writes = remoteWrites(ev.tool_name, input);
    if (writes.length && ev.session_id) {
        const seen = seenWrites(ev.session_id);
        const again = writes.filter((w) => seen[w]);
        if (again.length && !asked(ev.transcript_path, now, ASKS_CHANGE)) {
            return `Job guard: not run. ${again.join(', ')} on the server was already changed in this chat. `
                + 'Settings tuned again and again (a slot count set four times) unsettle every run that reads them. '
                + 'Decide the value once from evidence, then ask the person before changing it again.';
        }
        for (const w of writes) seen[w] = now;
        saveWrites(ev.session_id, seen);
    }
    return '';
}

function main() {
    let ev;
    try { ev = JSON.parse(fs.readFileSync(0, 'utf8') || '{}'); } catch { process.exit(0); }
    let why = '';
    try { why = judge(ev); } catch { process.exit(0); }
    if (!why) process.exit(0);
    process.stderr.write(why + '\n');
    process.exit(2);
}
if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) main();

