// Standing lessons — army discipline's memory link. On SessionStart it reads the app's
// memory (~/.ai-builder/memory: this project's file and the global one) and puts the newest
// lessons (records tagged "lesson" or "aar") into the chat's context, so every task starts
// with what earlier after-action reviews learned. Read-only; on any problem it adds nothing.
import crypto from 'node:crypto';
import fs from 'node:fs';
import os from 'node:os';
