// Live notes — steer a running workflow without stopping it.
//
// Fires on PreToolUse for Workflow. It creates <notes folder>/live-notes/<name>.md (the app's
// notes folder for the project, outside the repo — see notesDir) and
// rewrites the script so EVERY agent(...) prompt starts with a short instruction: read that
// notes file once (newer than the brief, wins where they conflict) and log at most ~6
// result lines to <name>.progress.log. The orchestrator then changes a running workflow by
// writing into the notes file — agents that start afterwards pick it up. The app archives
// both files when the workflow ends (src/live-notes.js). On any problem it ALLOWS the
// launch unchanged — a broken hook must never block work.
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { lessonsContext } from './lessons.mjs';

export const MARK = '// live-notes: on';
export const safeName = (n) => String(n || '').trim().replace(/[^A-Za-z0-9._-]+/g, '-').replace(/^[-.]+|-+$/g, '').slice(0, 80);
// In the app's notes folder for this project (outside the repo, AIB_PROJECT_DATA);
// <project>/.claude/live-notes only for a chat started without the app.
export const notesDir = (project) => {
    const data = (process.env.AIB_PROJECT_DATA || '').trim();
    return data ? path.join(data, 'live-notes') : path.join(project, '.claude', 'live-notes');
};

export function workflowName(script) {
    const m = /export\s+const\s+meta\s*=\s*\{[\s\S]*?\bname\s*:\s*(['"`])([^'"`]+)\1/.exec(String(script || ''));
    return m ? safeName(m[2]) : '';
}

// Army discipline for every workflow agent: the lessons already learned (project + global
// memory, read at launch), a before-action check, and an after-action review in its Return
// when it fails — its lesson goes back into memory.
export function discipline(lessons = '') {
    return [
        'DISCIPLINE (army-discipline): before acting, settle in a few lines of thought: the intent behind your goal (adapt to it if the plan breaks), the standard that proves done, who else touches the same files (live notes, other agents — stay out of their way), and what could go wrong with the fallback.',
        lessons ? `${lessons}\nApply these lessons; a reviewed mistake must not happen twice.` : '',
        'If you end NO-GO, BLOCKED, miss your Done-when or anything fails: add an AFTER-ACTION block to your Return, from evidence — Planned (quote your brief), Actual (facts + source), Cause (confirmed, or "unconfirmed" + what would confirm it), Change (one concrete fix). Then save the lesson: memory_save({ text: "When <situation>, <do this> — because <what happened>.", tags: ["lesson", "aar"], scope: "project" or "global" when it applies to any project }). If memory_save is not available, put it in your Return as "LESSON: <sentence> (project|global)" for the orchestrator to save.',
