}

// The text every agent's prompt starts with. `label` is filled in at run time.
export function preamble(notes, log, lessons = '') {
    const j = JSON.stringify;
    if (!notes) return [discipline(lessons), '', ''].join('\n');
    return [
        discipline(lessons),
        `LIVE NOTES: before anything else, read ${notes} once (cat ${j(notes)} 2>/dev/null). Use this absolute path even inside a worktree (a worktree copy is stale). Its notes are newer than your brief and override it where they conflict; a missing file means no notes. Never read it again, and never read the progress log.`,
        `PROGRESS: over your whole run append at most ~6 lines to ${log}: echo "$(date +%H:%M) \${label}: <result>" >> ${j(log)}. Each line states the deciding fact in plain words: a verdict (GO / NO-GO / BLOCKED), the number that decided it and where it came from, or the exact blocker and what would clear it. Never activity. Good: "21:40 verify-auth: NO-GO, 3 of 12 login tests fail (npm test output)". Bad: "21:40 verify-auth: running tests".`,
        '',
