// Usage origin. On SessionStart, a Claude session started from inside a Ninja Builder chat —
// an eval, a bake-off, a playbook audit or a CLI test an agent runs with `claude -p` — notes
// which chat started it, so the Usage tab counts it under that chat. The chat is the
// AIB_SESSION_ID in the session's environment, or in a parent process's when the runner
// cleaned the environment (the kit's evals do). Appends one line to the app's
// usage-origins.jsonl; the chat's own session (same id) and sessions outside the app write
// nothing. Never blocks: any problem and it does nothing.
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { execFileSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';

const ID = /^[A-Za-z0-9_-]{6,80}$/;

// The environment of a parent process (macOS `ps -E`, Linux /proc): only the AIB_ keys we need.
function envOf(pid, platform) {
    try {
        if (platform === 'linux') {
            const raw = fs.readFileSync(`/proc/${pid}/environ`, 'latin1').split('\0');
            const ppid = Number((/PPid:\s*(\d+)/.exec(fs.readFileSync(`/proc/${pid}/status`, 'latin1')) || [])[1]) || 0;
            const env = {};
            for (const kv of raw) { const i = kv.indexOf('='); if (i > 0 && kv.startsWith('AIB_')) env[kv.slice(0, i)] = kv.slice(i + 1); }
            return { env, ppid };
        }
        if (platform !== 'darwin') return null;
        const out = execFileSync('ps', ['-E', '-ww', '-o', 'ppid=,command=', '-p', String(pid)], { encoding: 'latin1', timeout: 1500, stdio: ['ignore', 'pipe', 'ignore'] });
        const ppid = Number((/^\s*(\d+)/.exec(out) || [])[1]) || 0;
        const env = {};
        for (const k of ['AIB_SESSION_ID', 'AIB_PROJECT_ROOT', 'AIB_PROJECT_DATA', 'AIB_DATA_DIR']) {
            const m = new RegExp(`(?:^|\\s)${k}=(\\S+)`).exec(out);
            if (m) env[k] = m[1];
        }
        return { env, ppid };
    } catch { return null; }
}

// → { o: origin chat, p: its project, env } or null.
export function findOrigin(sid, { env = process.env, ppid = process.ppid, platform = process.platform, lookup = envOf } = {}) {
    const mine = String(sid || '');
    const pick = (e) => (e && e.AIB_SESSION_ID && ID.test(e.AIB_SESSION_ID) && e.AIB_SESSION_ID !== mine ? { o: e.AIB_SESSION_ID, p: e.AIB_PROJECT_ROOT || '', env: e } : null);
    if (env.AIB_SESSION_ID) return pick(env); // set: this is a chat (its own id) or runs under one
    // A cleaned environment: walk up (the hook → this CLI → the runner → the chat's shell → the chat).
    for (let i = 0, pid = ppid; i < 16 && pid > 1; i++) {
        const r = lookup(pid, platform);
        if (!r) return null;
        const hit = pick(r.env);
        if (hit) return hit;
        if (r.env.AIB_SESSION_ID) return null; // the session's own chat process
        pid = r.ppid;
    }
    return null;
}

// The app's data folder: AIB_DATA_DIR, or the one AIB_PROJECT_DATA sits in (<data>/projects/<id>).
export function dataDirOf(env) {
    if (env.AIB_DATA_DIR) return env.AIB_DATA_DIR;
    if (env.AIB_PROJECT_DATA) return path.dirname(path.dirname(env.AIB_PROJECT_DATA));
    return path.join(os.homedir(), '.ai-builder');
}

export function recordOrigin(input, opts = {}) {
    const sid = input && input.session_id;
    if (!sid || !ID.test(String(sid))) return null;
    const hit = findOrigin(sid, opts);
    if (!hit) return null;
    const file = path.join(dataDirOf({ ...(opts.env || process.env), ...hit.env }), 'usage-origins.jsonl');
    const rec = { s: String(sid), o: hit.o, p: hit.p, c: String((input && input.cwd) || ''), t: Date.now() };
    try { fs.appendFileSync(file, JSON.stringify(rec) + '\n', { mode: 0o600 }); } catch { return null; }
    return rec;
}

if (process.argv[1] && fileURLToPath(import.meta.url) === path.resolve(process.argv[1])) {
    let raw = '';
    process.stdin.on('data', (d) => { raw += d; if (raw.length > 1 << 20) process.stdin.destroy(); });
    process.stdin.on('end', () => {
        try { recordOrigin(JSON.parse(raw || '{}')); } catch { /* nothing */ }
        process.exit(0);
    });
    process.stdin.on('error', () => process.exit(0));
}

