// Review Gate — the change is reviewed BEFORE the long test, not after it.
//
// Fires on PreToolUse for Bash and ssh tools. An agent ran each long server test first and
// had the change reviewed after; every review then found a flaw, so every ticket needed a
// fix and another full test (zoe-agi, 2026-11-02). This holds a long run (exit 2) until a
// reviewer subagent has approved exactly the code it would test: the git commit plus the
// uncommitted diff. Any change after the approval needs a new one.
//
// Long runs: the project's own patterns in <app project folder>/gates.json
// ({ "longRuns": ["regex", …] }), plus batch jobs (sbatch, qsub). The reviewer approves by running, from inside its subagent:
//   node "<this file>" --approve "<one line: what it checked>"
// Only a subagent may approve (the hook sees its agent_id); the main agent can't approve its
// own work, nor write the approval file by hand.
// --approve-rules "<summary>" approves a workflow's pass/fail rules instead and prints the
// id the workflow brief cites as "Rules checked: <id>" (see brief-gate).
// On any parse problem it ALLOWS: a broken hook must never block work.
import crypto from 'node:crypto';
import { spawnSync } from 'node:child_process';
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const SELF = fileURLToPath(import.meta.url);
// Batch jobs everywhere; anything else is the project's call (a test command is quick in one
// project and an hour on a server in another, and a pattern like "ssh … cargo test" also
// matched a pgrep looking FOR such runs).
const DEFAULT_LONG = [/(^|[\s;&|(])(sbatch|qsub)\b/];

export function projectData() {
    return (process.env.AIB_PROJECT_DATA || '').trim();
}
export function reviewsDir(data = projectData()) {
    return data ? path.join(data, 'reviews') : '';
}
export function longRunPatterns(data = projectData()) {
    const own = [];
    try {
        const cfg = JSON.parse(fs.readFileSync(path.join(data, 'gates.json'), 'utf8'));
        for (const p of Array.isArray(cfg.longRuns) ? cfg.longRuns : []) { try { own.push(new RegExp(String(p))); } catch { /* skip a bad pattern */ } }
    } catch { /* no project patterns */ }
