    return r.status === 0 ? String(r.stdout || '') : null;
}
export function changeKey(cwd) {
    const head = git(cwd, ['rev-parse', 'HEAD^{tree}']); // the code, not the commit: a notes-only commit keeps the approval
    if (head == null) return '';
    const diff = git(cwd, ['diff', '--no-ext-diff', '--no-textconv', 'HEAD']) || '';
    const untracked = git(cwd, ['ls-files', '--others', '--exclude-standard']) || '';
