export function approved(key, dir = reviewsDir()) {
    return !!key && !!dir && fs.existsSync(path.join(dir, `${key}.json`));
}

// The approval is the WHOLE command: nothing chained before or after it (`… --approve x; echo
// > reviews/…` would otherwise ride along).
const APPROVE_RE = /^\s*node\s+("[^"\n]*review-gate\.mjs"|'[^'\n]*review-gate\.mjs'|\S*review-gate\.mjs)\s+--approve(-rules)?\s+("[^"\n]*"|'[^'\n]*')\s*$/;
// The approval file is written only by this script, run from a subagent.
function touchesReviews(cmd, dir) {
    if (!dir || APPROVE_RE.test(cmd)) return false;
    return cmd.includes(dir) || /\$\{?AIB_PROJECT_DATA\b/.test(cmd) || /(^|[\s'"/])reviews\/[^\s'"]*\.json/.test(cmd) || /review-gate\.mjs[^\n]*--approve/.test(cmd);
}
const inside = (file, dir) => { const rel = path.relative(dir, path.resolve(String(file || ''))); return !!rel && !rel.startsWith('..') && !path.isAbsolute(rel); };

// → '' (allow) or the reason it is held.
export function judge(ev, { data = projectData(), keyOf = changeKey } = {}) {
    const input = ev.tool_input || {};
    const dir = reviewsDir(data);
    if (!dir) return '';
    const cmd = commandOf(ev.tool_name, input);
    if (cmd && APPROVE_RE.test(cmd)) {
        return ev.agent_id ? '' : 'Review gate: an approval must come from a reviewer subagent, not from the agent whose work it is. Launch a reviewer (Agent) to check the change; it runs this approval when it passes.';
    }
    if ((cmd && touchesReviews(cmd, dir)) || (/^(Write|Edit|MultiEdit|NotebookEdit)$/.test(String(ev.tool_name)) && inside(input.file_path || input.notebook_path, dir))) {
        return 'Review gate: approvals are written only by a reviewer subagent, through the review gate.';
    }
