// --approve / --approve-rules, run by the reviewer.
function approve(rules, summary) {
    const dir = reviewsDir();
    if (!dir) { process.stdout.write('No app project folder (AIB_PROJECT_DATA): nothing to approve.\n'); return 0; }
    fs.mkdirSync(dir, { recursive: true });
    const key = rules ? `rules-${crypto.randomBytes(5).toString('hex')}` : changeKey(process.cwd());
    if (!key) { process.stdout.write('Not a git repository here: run this from the folder the change is in.\n'); return 1; }
    fs.writeFileSync(path.join(dir, `${key}.json`), JSON.stringify({ at: new Date().toISOString(), cwd: process.cwd(), summary: String(summary || '').slice(0, 500) }));
    process.stdout.write(rules ? `Rules approved. The workflow brief cites: Rules checked: ${key}\n` : `Change approved (${key}). The long run can start; any later change needs a new review.\n`);
    return 0;
}

function main() {
    const flag = process.argv[2];
    if (flag === '--approve' || flag === '--approve-rules') {
        if (process.argv.length !== 4) { process.stdout.write('Usage: --approve "<one line: what you checked>"\n'); process.exit(1); }
        process.exit(approve(flag === '--approve-rules', process.argv[3]));
