// Risk Gate — a per-action checkpoint behind the plain-language Autonomy dial.
//
// Fires on PreToolUse, before every tool call. It reads the person's chosen
// autonomy level from AIB_AUTONOMY (set by the server when it spawns the CLI),
// classifies how risky the call is, and either lets it through (exit 0) or holds
// it (exit code 2 + a plain-language message on stderr) so the model pauses and
// asks the person first. Like the deny-list, this runs even under
// --dangerously-skip-permissions. On any parse failure it ALLOWS — a broken hook
// must never break the build.
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const LEVELS = ['build', 'check', 'approve'];

export function normalizeLevel(v) {
    const l = String(v || '').trim().toLowerCase();
    return LEVELS.includes(l) ? l : 'build';
}

const READ_ONLY_TOOLS = new Set(['Read', 'Grep', 'Glob', 'LS', 'NotebookRead']);
const WRITE_TOOLS = new Set(['Write', 'Edit', 'MultiEdit', 'NotebookEdit']);

const SAFE_HEADS = new Set([
    'ls', 'cat', 'pwd', 'grep', 'egrep', 'fgrep', 'rg', 'echo', 'head', 'tail',
    'wc', 'which', 'type', 'file', 'stat', 'printenv', 'date', 'whoami',
    'hostname', 'tree', 'sort', 'uniq', 'cut', 'basename', 'dirname', 'realpath',
]);

function bashHeadSafe(segment) {
    const toks = segment.trim().split(/\s+/).filter(Boolean);
    if (!toks.length) return true;
    let i = 0;
    while (i < toks.length && /^[A-Za-z_][A-Za-z0-9_]*=/.test(toks[i])) i++;
    const head = (toks[i] || '').replace(/^.*\//, '');
    const rest = toks.slice(i + 1);
    if (SAFE_HEADS.has(head)) return true;
    // `env` alone (or with NAME=VALUE only) lists variables; any option or command makes it run something.
    if (head === 'env') return rest.every((t) => /^[A-Za-z_][A-Za-z0-9_]*=[^\s'"\\]*$/.test(t));
