    if (head === 'find') {
        if (/['"\\]/.test(segment)) return false;
        const READ_ONLY_FIND = /^-(name|iname|path|ipath|type|maxdepth|mindepth|mtime|mmin|newer|size|empty|print|print0|prune|not|o|a|or|and|depth|follow|L|H|P|regex|iregex|perm|user|group|links|samefile)$/;
        return rest.every((t) => !t.startsWith('-') || READ_ONLY_FIND.test(t));
    }
    if (head === 'git') return /^(status|log|diff|show|remote)$/i.test(rest[0] || '');
    if (head === 'node') return rest.some((t) => t === '--check' || t === '-c');
    return false;
}

export function isReadOnlyBash(command) {
    const cmd = String(command || '');
    if (/[>]/.test(cmd)) return false;
    const segments = cmd.split(/\|\||&&|;|\||&/).map((s) => s.trim()).filter(Boolean);
    if (!segments.length) return false;
    return segments.every(bashHeadSafe);
}

export function classifyBash(command) {
    const cmd = String(command || '');
    const c = cmd.toLowerCase();

    if (/\b(deploy|publish)\b/.test(c)) return 'HIGH';
    if (/\bgit\s+push\b/.test(c)) return 'HIGH';
    if (/(^|[\s;&|(/])(rm|rmdir)\s/.test(c)) return 'HIGH';
    if (/\bnpm\s+publish\b/.test(c)) return 'HIGH';
    if (/(^|[\s;&|(/])(ssh|scp)\s/.test(c)) return 'HIGH';
    if (/\b(sendmail|mail|mailx|mutt)\b/.test(c)) return 'HIGH';
    if (/\bdrop\s+(table|database)\b|\btruncate\b|\bdelete\s+from\b/.test(c)) return 'HIGH';
    if (/\b(curl|wget)\b/.test(c)) {
