    if (/(^|[\s;&|(/])(mkdir|mv|cp|chmod|touch|ln)\s/.test(c)) return 'MEDIUM';
    if (/\bgit\s+(commit|add|init|checkout|branch|merge|stash|rm|restore|reset|tag)\b/.test(c)) return 'MEDIUM';

