export function classifyFileWrite(toolInput, cwd) {
    const fp = toolInput && (toolInput.file_path || toolInput.path || toolInput.notebook_path);
    if (!fp) return 'MEDIUM';
    const abs = path.isAbsolute(fp) ? fp : path.resolve(cwd || process.cwd(), fp);
    const low = abs.toLowerCase();
    const base = path.basename(low);
    if (base.startsWith('.env') && base !== '.env.example') return 'HIGH';
    if (/credential|secret|id_rsa|\.pem$|\.key$|\.p12$|\.pfx$/.test(low)) return 'HIGH';
