export function classifyRisk(toolName, toolInput, cwd) {
    const name = String(toolName || '');
    if (READ_ONLY_TOOLS.has(name)) return 'SAFE';
    if (name === 'Bash') return classifyBash(toolInput && toolInput.command);
    if (WRITE_TOOLS.has(name)) return classifyFileWrite(toolInput, cwd);
    return 'MEDIUM';
}

export function decide(level, risk) {
    const lvl = normalizeLevel(level);
    if (lvl === 'build') return { block: false };
    if (lvl === 'check') return { block: risk === 'HIGH' };
    return { block: risk === 'HIGH' || risk === 'MEDIUM' };
}

