    if (at < 0) return null;
    const idx = cmd.indexOf(toks[at], cmd.indexOf(' add '));
    if (idx < 0) return null;
    const q = (s) => `"${s.replace(/(["\\$`])/g, '\\$1')}"`;
    const command = `mkdir -p ${q(path.dirname(dir))} && ` + cmd.slice(0, idx) + q(dir) + cmd.slice(idx + toks[at].length);
    return { command, dir };
}

export async function evaluateToolCall(data, { level = process.env.AIB_AUTONOMY, guardOnly = false, rewrite = false } = {}) {
    data = data && typeof data === 'object' ? data : {};
    const wide = scansAppData(data.tool_name, data.tool_input || {});
    if (wide) {
        return { block: true, message:
            `BLOCKED — this scans ${wide === '/' ? 'the whole disk' : wide}, which reaches other apps' private data (Mail, Photos, Messages…) ` +
                'and makes macOS interrupt the person with an "Ninja Builder would like to access data from other apps" prompt. ' +
                'Search the project, or a specific folder (e.g. ~/Projects, ~/.ai-builder), instead; for a file name use `find ~/Projects -name <name>` or `mdfind -onlyin ~/Projects -name <name>` (Spotlight without -onlyin reaches Photos, Music and iCloud too).\n' };
    }
    const tmpWide = scansTempRoot(data.tool_name, data.tool_input || {});
    if (tmpWide) {
        return { block: true, message:
            `BLOCKED — this searches the whole temp folder (${tmpWide}): every app's and every agent's scratch files, ` +
                'hundreds of thousands of them. One such search ran at 500% CPU and slowed the whole computer. ' +
                'Search only the subfolder you made or need (e.g. "$TMPDIR/my-run", /tmp/claude-501/<project>), or the project itself.\n' };
    }
    const chrome = startsRealChrome(data.tool_name, data.tool_input || {});
    if (chrome) {
        const shell = headlessShell();
        return { block: true, message:
            `BLOCKED — this starts ${chrome}, which puts an extra Chrome icon in the person's Dock while their own Chrome is open (even headless, even briefly). ` +
                (shell ? `For a headless screenshot / PDF / page render use the headless browser that has no Dock icon: "${shell}" (same flags as Chrome: --headless --screenshot=… / --print-to-pdf=…). ` : 'For a headless screenshot / PDF / page render use Playwright (its chromium headless shell has no Dock icon). ') +
                'For an image conversion prefer rsvg-convert / sips / magick. To show the person a page, use the Preview pane (preview_open).\n' };
    }
    const wt = worktreeOutside(data.tool_name, data.tool_input || {}, data.cwd || process.cwd());
    // Don't just refuse: put the worktree where it belongs and let the command run (the
    // Claude hook rewrites the command; callers that can't rewrite still get the block).
    const fix = wt && rewrite ? worktreeFix(data.tool_input || {}, wt) : null;
    if (fix) {
        const rest = await evaluateToolCall({ ...data, tool_input: { ...(data.tool_input || {}), command: fix.command } }, { level, guardOnly, rewrite: false });
        if (!rest.block) return { block: false, rewrite: { command: fix.command }, note: `The worktree goes in the app's own folder for this project: ${fix.dir} (moved from ${wt}).` };
    }
    if (wt) {
        return { block: true, message:
            `BLOCKED — this creates a git worktree at ${wt}, outside the project folder. Extra folders next to the project (or in /tmp) look like other projects to the person and clutter their disk. ` +
                'Create worktrees in the app\'s own hidden folder for this project: `git worktree add "$AIB_PROJECT_DATA/worktrees/<name>" -b <name>` (or inside the repo under .claude/worktrees/<name>, git-ignored), and remove it when done.\n' };
    }
    const app = modifiesApps(data.tool_name, data.tool_input || {}, data.cwd || process.cwd());
    if (app) {
        return { block: true, message:
            `BLOCKED — this is ${app}, which makes macOS warn the person that Ninja Builder tried to modify apps on their Mac. ` +
                "Don't change files inside .app bundles outside the project, and don't run `playwright install` (use the browsers already installed; Playwright's default headless Chromium works).\n" };
    }
    const kc = keychainBrowser(data.tool_name, data.tool_input || {});
    if (kc) {
        return { block: true, message:
            `BLOCKED — this launches ${kc}, which makes macOS ask the person for their keychain password ("Chromium Safe Storage"). ` +
                "Use Playwright's default headless browser (chromium.launch() with no executablePath / channel / headless:false), " +
                "and pass args: ['--use-mock-keychain', '--password-store=basic'] to any Chromium you start.\n" };
    }
    const rt = redtrackWrite(data.tool_name, data.tool_input || {});
    if (rt) {
        return { block: true, message:
            `BLOCKED — tracker access (RedTrack / Voluum) is read-only in Ninja Builder (${rt}). Use the read tools (get…/list…/report…) to look things up; ` +
                'anything that would create, change, pause, delete or re-budget in the tracker is for the person to do there themselves — tell them exactly what to change and why.\n' };
    }
    // Branch guard: git commands act on exactly the branches the person named (no
    // invented names, no "staging" when they said "all-staging") — see branch-guard.mjs.
    let branchIssue = '';
    // Loaded on demand: a missing/broken branch-guard file must never disable the guards above.
    try { branchIssue = (await import('./branch-guard.mjs')).checkGitBranches(data); } catch { branchIssue = ''; }
    if (branchIssue) return { block: true, message: `BLOCKED — ${branchIssue}\n` };
    // The app-level guard plugin (native / extras profiles) runs only the checks above.
    if (guardOnly) return { block: false };

    const lvl = normalizeLevel(level);
    if (lvl === 'build') return { block: false };

    const cwd = typeof data.cwd === 'string' && data.cwd ? data.cwd : process.cwd();
    const name = data.tool_name;
    const input = data.tool_input || {};
    const risk = classifyRisk(name, input, cwd);
    const { block } = decide(lvl, risk);
    if (!block) return { block: false };

    const tier = risk === 'HIGH' ? 'high' : 'medium';
    return { block: true, message:
        `NEEDS APPROVAL (${lvl}) — this is a ${tier}-risk action: ${shortWhat(name, input)}. ` +
            'Do not run it yet. Tell the person in plain language what you want to do and why, and wait for their OK.\n' };
}

