try {
    directRun = process.argv[1]
        ? fs.realpathSync(path.resolve(process.argv[1])) === fs.realpathSync(fileURLToPath(import.meta.url))
        : true;
} catch {
    directRun = true;
}
// Imported as a library (the OpenCode guard plugin runs inside OpenCode's own binary, whose
// argv[1] is not a file — the check above would read as a direct run and exit the server).
if (directRun && !globalThis.__AIB_GATE_LIBRARY) main();

