// Target Gate — re-anchors a session to its pinned main target at the one moment
// drift does the most damage: a "done" claim.
//
// Fires on Stop. It only acts when the working directory has a
// `.builder/target.md` (a target the person pinned for this session) AND the
// model is actually claiming it's finished. A turn that pauses to ask a question,
// or to hand off one blocked item while other work continues, is left alone — the
// gate must never punish the legitimate sub-tasks that lead to the target.
//
// It does NOT verify the target is met (it can't know that) and it does NOT wall
// the session shut: the Stop loop-guard means it nudges at most once per stop
// sequence. The nudge simply forces the model to check the finished work against
// the pinned goal and, if genuinely delivered, hand the achieve/unpin decision to
// the person — never to silently declare a tangent "done" while the target stands.
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

// Resolve a build-trail artifact. The app relocates the trail OUT of the project
// to AIB_BUILDER_DIR; prefer that, but fall back to the legacy `<cwd>/.builder`
// (and prefer whichever actually exists) so the gate still fires if the agent
// wrote there out of habit, or when run without the app (env unset).
export function resolveArtifact(cwd, name) {
    const env = (process.env.AIB_BUILDER_DIR || '').trim();
    const candidates = [];
    if (env) candidates.push(path.join(env, name));
    candidates.push(path.join(cwd, '.builder', name));
    for (const c of candidates) if (fs.existsSync(c)) return c;
    return candidates[0];
}

export function readTarget(cwd) {
    try {
        const raw = fs.readFileSync(resolveArtifact(cwd, 'target.md'), 'utf8');
        // Strip the "# Main target" heading; the goal is the first non-empty body line.
        const body = raw.replace(/^#.*$/m, '').trim();
        return body || '';
    } catch {
        return '';
    }
}

export function claimsDone(message) {
    return /\b(done|finished|complete|completed|ready to (hand|ship|deploy|go|launch)|handed off|all set|that'?s (it|everything)|shipped it)\b/i.test(
        String(message || '')
    );
}

function main() {
    const allow = () => process.exit(0);

    let raw = '';
    try {
        raw = fs.readFileSync(0, 'utf8');
    } catch {
        allow();
    }

    let data = {};
    try {
        data = JSON.parse(raw || '{}');
    } catch {
        allow();
    }

    // Loop guard: never block twice in a row (prevents an infinite stop loop and
    // keeps this a one-time nudge, not a wall).
    if (data.stop_hook_active === true) allow();

    const cwd = typeof data.cwd === 'string' && data.cwd ? data.cwd : process.cwd();
    const target = readTarget(cwd);
    if (!target) allow(); // nothing pinned → not a targeted session

    // Only nudge on an actual completion claim. Pausing to ask, or parking one
    // blocked item, must be allowed to stop.
    if (!claimsDone(data.last_assistant_message)) allow();

    const out = [
        'HOLD — a main target is still pinned for this session; do not sign off until it is genuinely delivered:',
        `  "${target}"`,
        'Check the work you just finished against this exact goal.',
        '  - If it IS fully delivered: say so plainly, and let the person confirm and unpin the target — you do not mark it achieved yourself.',
        '  - If it is NOT: name in one line what still stands between here and the target, then keep working on it.',
        'Sub-tasks and detours that served the target were correct; the only thing being checked is that the pinned goal itself is actually met before you call it done.',
    ];
    process.stderr.write(out.join('\n') + '\n');
    process.exit(2);
}

let directRun = true;
try {
    directRun = process.argv[1]
        ? fs.realpathSync(path.resolve(process.argv[1])) === fs.realpathSync(fileURLToPath(import.meta.url))
        : true;
} catch {
    directRun = true;
}
if (directRun) main();

