        if ((m = adm.exec(text))) {
            finding(out, {
                severity: 'critical', rule: 'firebase-admin-client', file: rel, line: lineOf(text, m.index),
                title: 'Browser code loads firebase-admin',
                why: 'firebase-admin needs a service-account key with full access to your Firebase project; in browser code that key ends up public.',
                fix: FIX.adminInClient,
            });
        }
    }
    // Public storage buckets created in code.
    const cb = /createBucket\s*\([^)]{0,200}?public\s*:\s*true/g;
    while ((m = cb.exec(text))) {
        finding(out, {
            severity: 'warning', rule: 'public-bucket', file: rel, line: lineOf(text, m.index),
            title: 'A storage bucket is created as public',
            why: 'Anyone with a file\'s link can download it — fine for logos and product photos, not for user uploads or invoices.',
            fix: FIX.bucket,
        });
    }
    if (ctx.production) {
        const cors = [
            /Access-Control-Allow-Origin['"]?\s*[,:=]\s*['"]\*['"]/gi,
            /\bcors\s*\(\s*\{[^}]{0,200}?origin\s*:\s*['"]\*['"]/g,
            /\bCORS_(?:ORIGIN_)?ALLOW_ALL(?:_ORIGINS)?\s*=\s*True\b/g,
            /\ballow_origins\s*=\s*\[\s*['"]\*['"]\s*\]/g,
        ];
        for (const re of cors) {
            while ((m = re.exec(text))) {
                finding(out, {
                    severity: 'warning', rule: 'cors-any', file: rel, line: lineOf(text, m.index),
                    title: 'The API accepts calls from any website (CORS *)',
                    why: 'Any site on the internet can call this API from a visitor\'s browser. Fine for public read-only data, risky for anything behind a login.',
                    fix: FIX.cors,
                });
            }
        }
        const dbg = [
            /^\s*DEBUG\s*=\s*True\b/gm,
            /\bapp\.run\([^)]*debug\s*=\s*True/g,
        ];
        const isProdConfig = /(^|\/)settings\.py$|(^|\/)(settings|config)\/(prod|production)[^/]*\.py$|\.py$/.test(rel);
        if (isProdConfig && !/(^|\/)(local|dev|development|test)[^/]*\.py$/.test(rel)) {
            for (const re of dbg) {
                while ((m = re.exec(text))) {
                    finding(out, {
                        severity: 'warning', rule: 'debug-mode', file: rel, line: lineOf(text, m.index),
                        title: 'Debug mode is on',
                        why: 'With debug on, an error page shows visitors your code, settings and sometimes secrets.',
                        fix: FIX.debug,
                    });
                }
            }
        }
        if (/(^|\/)\.env\.production$|(^|\/)[^/]*prod[^/]*\.(json|ya?ml|toml|env)$/i.test(rel)) {
            const re = /^\s*["']?(?:APP_)?DEBUG["']?\s*[:=]\s*["']?(?:true|1|on)["']?\s*,?\s*$/gim;
            while ((m = re.exec(text))) {
                finding(out, {
                    severity: 'warning', rule: 'debug-mode', file: rel, line: lineOf(text, m.index),
                    title: 'Debug mode is on in the production settings',
                    why: 'With debug on, an error page shows visitors your code, settings and sometimes secrets.',
                    fix: FIX.debug,
                });
            }
        }
    }
}

// Debug switched on in env/config files that ship (not dev/test/local or template ones).
const DEV_NAMED = /(^|\/|[._-])(local|dev|development|test|testing|example|sample|template)([._-][^/]*)?$|(^|\/)(tests?|__tests__|\.vscode|\.idea)\//i;
function scanDebugConfig(text, rel, out) {
    const base = path.basename(rel);
    const env = ENV_FILE.test(base);
    if (env ? ENV_TEMPLATE.test(base) || /^\.env\.(local|dev|development|test|testing)(\..+)?$/i.test(base) : DEV_NAMED.test(rel.replace(/\.[^./]+$/, ''))) return;
    if (/(^|\/)\.env\.production$|(^|\/)[^/]*prod[^/]*\.(json|ya?ml|toml|env)$/i.test(rel)) return; // the production-settings rule (scanCode) reports these
    let re;
    if (env) re = /^\s*(?:export\s+)?((?:APP_|FLASK_|DJANGO_|NUXT_|NEXT_PUBLIC_|VITE_)?DEBUG)\s*=\s*["']?(?:true|1|on|yes)["']?\s*(?:#.*)?$/gim;
    else if (/\.(json|ya?ml|toml|ini|cfg|conf|properties)$/i.test(rel) && /(^|\/)[^/]*(config|settings|app|application|appsettings)[^/]*$/i.test(rel)) {
        re = /^\s*["']?((?:APP_|FLASK_|DJANGO_)?DEBUG|debug)["']?\s*[:=]\s*["']?(?:true|1|on|yes)["']?\s*,?\s*(?:#.*)?$/gm;
    } else return;
    let m;
    while ((m = re.exec(text))) {
        finding(out, {
            severity: 'warning', rule: 'debug-mode', file: rel, line: lineOf(text, m.index),
            title: `Debug mode is switched on (${m[1]})`,
            why: 'With debug on, an error page shows visitors your code, settings and sometimes secrets.',
            fix: FIX.debug,
        });
    }
}

// A database link with the password written in it: postgres://user:pass@host/db.
const DB_URL_RE = /\b((?:postgres(?:ql)?|mysql|mariadb|mongodb(?:\+srv)?|rediss?|amqps?|mssql|sqlserver|cockroachdb)):\/\/([^\s:@/'"`]+):([^\s@/'"`]+)@([^\s/:'"`?#]+)/gi;
const DUMMY_PASSWORDS = /^(password|passw(or)?d|pass|pwd|pw|secret|user|username|db_?pass(word)?|xxx+|\*+|\.\.\.|…)$/i;
const LOCAL_HOST = /^(localhost|127\.\d+\.\d+\.\d+|0\.0\.0\.0|\[?::1\]?|host\.docker\.internal)$/i;
function scanDbUrls(text, rel, out, where) {
    if (ENV_TEMPLATE.test(path.basename(rel)) || /\.(md|mdx|txt|rst|adoc)$/i.test(rel)) return; // templates and docs show sample links
    DB_URL_RE.lastIndex = 0;
    let m;
    while ((m = DB_URL_RE.exec(text))) {
        const [whole, scheme, , pass, host] = m;
        if (PLACEHOLDER.test(whole) || FAKE_VALUE.test(pass) || DUMMY_PASSWORDS.test(pass)) continue;
        if (/^[$%{<[]/.test(pass) || /\$\{|\{\{|%\(/.test(pass)) continue; // a variable, not a password
        if (LOCAL_HOST.test(host) || !host.includes('.')) continue; // a dev box or a compose service name (db, postgres)
        const severity = where !== 'output' && TEST_FILE.test(rel) ? 'warning' : 'critical';
        finding(out, {
            severity, rule: 'db-url-password', file: rel, line: lineOf(text, m.index),
            title: `A ${scheme.toLowerCase()} database link has its password written in ${where === 'output' ? 'the publish folder' : 'the project'}`,
            why: 'Anyone who sees this file can log in to the database with it and read or delete the data.',
            fix: FIX.dbUrl, evidence: `${scheme}://…:${redact(pass)}@${host}`,
        });
    }
}

// SQL glued together from what the visitor sent (SQL injection). Only the plain shapes:
// a SQL string with req.body/query/params (or request.args/form, $_GET/$_POST) pasted in.
// SELECT needs a column list then FROM <table> ("Select a size from the list" is prose).
const SQL_COL = String.raw`[\w."\x60*()]+(?:\s+as\s+\w+)?`;
const SQL_HEAD = String.raw`(?:select\s+(?:distinct\s+)?${SQL_COL}(?:\s*,\s*${SQL_COL})*\s+from\s+[\w."\x60]|insert\s+into\b|update\s+[\w."\x60]+\s+set\b|delete\s+from\b)`;
// A quoted SQL string, either quote: "… SELECT … FROM …" or '… INSERT INTO …'.
const SQL_STR = String.raw`(?:"[^"\n]*?${SQL_HEAD}[^"\n]*"|'[^'\n]*?${SQL_HEAD}[^'\n]*')`;
const SQL_INPUT_RULES = [
    // JS/TS template literal: `SELECT … ${req.query.id}`
    { lang: /\.(m?[jt]sx?|cjs|cts|mts)$/i, re: new RegExp(String.raw`\x60[^\x60]*?${SQL_HEAD}[^\x60]*?\$\{\s*(?:req|request|ctx\.request|ctx)\.(?:body|query|params)\b`, 'gi') },
    // JS/TS concatenation: "SELECT … " + req.body.name
    { lang: /\.(m?[jt]sx?|cjs|cts|mts)$/i, re: new RegExp(String.raw`${SQL_STR}\s*\+\s*(?:req|request|ctx\.request|ctx)\.(?:body|query|params)\b`, 'gi') },
    // Python f-string / % / + / .format with Flask, Django or FastAPI request data
    { lang: /\.py$/i, re: new RegExp(String.raw`\bf["'][^"'\n]*?${SQL_HEAD}[^"'\n]*?\{\s*request\.(?:args|form|values|json|GET|POST|data|query_params)\b`, 'gi') },
    { lang: /\.py$/i, re: new RegExp(String.raw`${SQL_STR}\s*(?:%|\+|\.format\()\s*\(?\s*request\.(?:args|form|values|json|GET|POST|data|query_params)\b`, 'gi') },
    // PHP: "SELECT … $_GET['id']" or "SELECT … " . $_POST['x']
    { lang: /\.(php|phtml)$/i, re: new RegExp(String.raw`(?:"[^"\n]*?${SQL_HEAD}[^"\n]*?|${SQL_STR}\s*\.\s*)\$_(?:GET|POST|REQUEST|COOKIE)\s*\[`, 'gi') },
];
function scanSqlInjection(text, rel, out) {
    for (const rule of SQL_INPUT_RULES) {
        if (!rule.lang.test(rel)) continue;
        rule.re.lastIndex = 0;
        let m;
        while ((m = rule.re.exec(text))) {
            finding(out, {
                severity: TEST_FILE.test(rel) ? 'warning' : 'critical', rule: 'sql-from-input', file: rel, line: lineOf(text, m.index),
                title: 'SQL is built from what the visitor sent',
                why: 'A visitor can type SQL of their own into that field and read, change or delete any data in the database (SQL injection).',
                fix: FIX.sql,
            });
        }
    }
}

// Firebase rules files.
function scanFirebaseRules(text, rel, out) {
    if (!/(^|\/)(firestore|storage|database)\.rules$|\.rules$/.test(rel)) return;
    const re = /allow\s+([a-z, ]+?)\s*(?::\s*if\s+true\s*)?;/g;
    let m;
    while ((m = re.exec(text))) {
        const stmt = m[0];
        const unconditional = /if\s+true/.test(stmt) || !/:\s*if/.test(stmt);
        if (!unconditional) continue;
        const write = /\b(write|create|update|delete)\b/.test(m[1]);
        finding(out, {
            severity: write ? 'critical' : 'warning', rule: write ? 'firebase-open-write' : 'firebase-open-read', file: rel, line: lineOf(text, m.index),
            title: write ? 'Firebase rules let anyone change data' : 'Firebase rules let anyone read data',
            why: write ? 'Anyone on the internet can add, change or delete data in your database or storage — no login needed.'
                : 'Anyone on the internet can read this data without logging in.',
            fix: FIX.rulesOpen,
        });
    }
}

// SQL: tables without row level security (Supabase) and public storage buckets.
const SQL_IDENT = String.raw`(?:"[^"]+"|[A-Za-z_][A-Za-z0-9_$]*)`;
function normTable(name) {
    const parts = name.split('.').map((p) => p.replace(/"/g, '').toLowerCase());
    return parts.length === 1 ? 'public.' + parts[0] : parts.join('.');
}
function scanSql(files, out, supabase) {
    const created = [];
    const rls = new Set();
    const createRe = new RegExp(String.raw`\bcreate\s+(?:unlogged\s+)?table\s+(?:if\s+not\s+exists\s+)?(${SQL_IDENT}(?:\.${SQL_IDENT})?)`, 'gi');
    const rlsRe = new RegExp(String.raw`\balter\s+table\s+(?:if\s+exists\s+)?(?:only\s+)?(${SQL_IDENT}(?:\.${SQL_IDENT})?)\s+enable\s+row\s+level\s+security`, 'gi');
    for (const { rel, text } of files) {
        const sql = text.replace(/--[^\n]*/g, (s) => ' '.repeat(s.length)).replace(/\/\*[\s\S]*?\*\//g, (s) => s.replace(/[^\n]/g, ' '));
        let m;
        createRe.lastIndex = 0;
        while ((m = createRe.exec(sql))) created.push({ table: normTable(m[1]), rel, line: lineOf(sql, m.index) });
        rlsRe.lastIndex = 0;
        while ((m = rlsRe.exec(sql))) rls.add(normTable(m[1]));
        // Public buckets: one statement mentioning storage.buckets with public = true.
        for (const stmt of sql.split(';')) {
            if (!/\bstorage\s*\.\s*buckets\b/i.test(stmt)) continue;
            const ins = /insert\s+into\s+storage\s*\.\s*buckets\s*\(([^)]*)\)\s*values\s*\(([^)]*)\)/i.exec(stmt);
            let isPublic = false;
            if (ins) {
                const cols = ins[1].split(',').map((s) => s.trim().replace(/"/g, '').toLowerCase());
                const vals = ins[2].split(',').map((s) => s.trim().toLowerCase());
                const i = cols.indexOf('public');
                isPublic = i >= 0 && vals[i] === 'true';
            } else if (/update\s+storage\s*\.\s*buckets\s+set\s+public\s*=\s*true/i.test(stmt)) isPublic = true;
            if (isPublic) {
                finding(out, {
                    severity: 'warning', rule: 'public-bucket', file: rel, line: lineOf(sql, sql.indexOf(stmt) + stmt.search(/\S/)),
                    title: 'A storage bucket is public',
                    why: 'Anyone with a file\'s link can download it — fine for logos and product photos, not for user uploads or invoices.',
                    fix: FIX.bucket,
                });
            }
        }
    }
    if (!supabase) return;
    for (const c of created) {
        if (!c.table.startsWith('public.')) continue; // other schemas are not exposed by the Supabase API
        if (rls.has(c.table)) continue;
        finding(out, {
            severity: 'critical', rule: 'table-without-rls', file: c.rel, line: c.line,
            title: `Table “${c.table.slice(7)}” has no row level security`,
            why: 'Supabase lets the browser query tables in the public schema with the public anon key. Without row level security, anyone can read and change every row.',
            fix: FIX.rls.replace('<name>', c.table.slice(7)),
        });
    }
}

function detectSupabase(dir, files) {
    if (files.some((f) => f.startsWith('supabase/'))) return true;
    try {
        const pkg = JSON.parse(fs.readFileSync(path.join(dir, 'package.json'), 'utf8'));
        const deps = { ...pkg.dependencies, ...pkg.devDependencies };
        return Object.keys(deps).some((d) => d.startsWith('@supabase/') || d === 'supabase');
    } catch { return false; }
}

// npm audit — opt-in, time-boxed. Injectable for tests.
export function runNpmAudit(dir, { timeoutMs = 25000, exec } = {}) {
    const run = exec || ((cwd) => spawnSync(process.platform === 'win32' ? 'npm.cmd' : 'npm', ['audit', '--omit=dev', '--json'],
        { cwd, encoding: 'utf8', timeout: timeoutMs, maxBuffer: 32 * 1024 * 1024 }));
    const r = run(dir);
    if (r.error || (r.status === null)) return { ok: false, reason: r.error?.code === 'ETIMEDOUT' || r.signal ? 'timed out' : 'npm is not available' };
    try {
        const j = JSON.parse(r.stdout || '{}');
        const v = j.metadata?.vulnerabilities;
        if (!v) return { ok: false, reason: j.error?.summary || 'no result' };
        const names = Object.entries(j.vulnerabilities || {})
            .filter(([, x]) => x.severity === 'critical' || x.severity === 'high').map(([n]) => n);
        return { ok: true, counts: v, names };
    } catch { return { ok: false, reason: 'could not read the result' }; }
}

/**
 * Scan a project before deploy.
 * @param {string} dir project folder
 * @param {{ outDir?: string, audit?: boolean, auditExec?: Function, production?: boolean }} opts
 */
export function scanProject(dir, opts = {}) {
    const root = path.resolve(dir);
    const findings = [];
    const isGit = git(root, ['rev-parse', '--is-inside-work-tree'])?.trim() === 'true';
    let files;
    let tracked = new Set();
    if (isGit) {
        const ls = git(root, ['ls-files', '-z', '--cached', '--others', '--exclude-standard']) || '';
        const cached = git(root, ['ls-files', '-z', '--cached']) || '';
        tracked = new Set(cached.split('\0').filter(Boolean));
        files = ls.split('\0').filter(Boolean);
    } else {
        files = walk(root);
    }
    files = files.slice(0, MAX_FILES);
    const ctx = { production: opts.production !== false };

    // .env and key files that git tracks.
    for (const rel of files) {
        const base = path.basename(rel);
        if (!isGit || !tracked.has(rel)) continue; // outside git, a local .env is normal; the publish-folder check covers it
        if (/(^|\/)(node_modules|tests?\/fixtures)\//.test(rel)) continue;
        if (ENV_FILE.test(base) && !ENV_TEMPLATE.test(base)) {
            finding(findings, {
                severity: 'critical', rule: 'env-tracked', file: rel,
                title: `${base} is saved in git`,
                why: isGit ? 'Everything in git is copied wherever the code goes — GitHub, teammates, the host. The keys in this file are effectively public.'
                    : 'This folder will be shared or uploaded as is, keys included.',
                fix: FIX.envTracked.replace('<file>', rel),
            });
        } else if (KEY_FILE.test(base) && !/\.pub$/.test(base)) {
            const t = readText(path.join(root, rel));
            if (t === null || /PRIVATE KEY/.test(t) || /\.(p12|pfx)$/i.test(base)) {
                finding(findings, {
                    severity: 'critical', rule: 'key-file-tracked', file: rel,
                    title: `Key file ${base} is saved in the project`,
                    why: 'A private key lets anyone who has it sign in as you or decrypt your traffic.',
                    fix: FIX.keyFile,
                });
            }
        }
    }
    // A real .env that git would pick up on the next commit.
    if (isGit) {
        for (const name of ['.env', '.env.local', '.env.production']) {
            if (!fs.existsSync(path.join(root, name)) || tracked.has(name)) continue;
            if (files.includes(name)) {
                finding(findings, {
                    severity: 'warning', rule: 'env-not-ignored', file: name,
                    title: `${name} is not in .gitignore`,
                    why: 'It is not committed yet, but the next "commit everything" will upload your keys with the code.',
                    fix: FIX.envIgnore,
                });
            }
        }
    }

    // Content scan of project files.
    const sqlFiles = [];
    for (const rel of files) {
        if (isSkippedPath(rel)) continue;
        const text = readText(path.join(root, rel));
        if (text === null) continue;
        scanSecrets(text, rel, findings, 'project');
        scanEntropy(text, rel, findings);
        scanCode(text, rel, findings, ctx);
        scanFirebaseRules(text, rel, findings);
        scanDebugConfig(text, rel, findings);
        scanDbUrls(text, rel, findings, 'project');
        scanSqlInjection(text, rel, findings);
        if (/\.sql$/i.test(rel)) sqlFiles.push({ rel, text });
    }
    scanSql(sqlFiles, findings, detectSupabase(root, files));

    // The folder about to be published.
    const outDirs = [];
    if (opts.outDir) outDirs.push(path.resolve(root, opts.outDir));
    else for (const d of BUILD_DIRS) { const p = path.join(root, d); if (fs.existsSync(p) && fs.statSync(p).isDirectory()) outDirs.push(p); }
    const outSkip = new Set(['node_modules', '.git', 'cache']);
    for (const od of outDirs) {
        const relBase = path.relative(root, od) || '.';
        for (const r of walk(od, { skipDirs: outSkip })) {
            const rel = relBase === '.' ? r : relBase + '/' + r;
            const base = path.basename(r);
            if (ENV_FILE.test(base) && !ENV_TEMPLATE.test(base)) {
                finding(findings, {
                    severity: 'critical', rule: 'env-in-output', file: rel,
                    title: `${base} is inside the folder that gets published`,
                    why: 'Every file in this folder becomes downloadable from your site, so anyone could fetch your keys at /' + r + '.',
                    fix: FIX.envOutput,
                });
                continue;
            }
            if (KEY_FILE.test(base) && !/\.pub$/.test(base)) {
                finding(findings, {
                    severity: 'critical', rule: 'key-file-in-output', file: rel,
                    title: `Key file ${base} is inside the folder that gets published`,
                    why: 'Every file in this folder becomes downloadable from your site.',
                    fix: FIX.envOutput,
                });
                continue;
            }
            if (BINARY_EXT.test(r) || /\.map$/.test(r)) continue;
            const text = readText(path.join(od, r));
            if (text !== null) { scanSecrets(text, rel, findings, 'output'); scanDbUrls(text, rel, findings, 'output'); }
        }
    }

    // Dependency audit.
    const hasLock = fs.existsSync(path.join(root, 'package-lock.json')) || fs.existsSync(path.join(root, 'npm-shrinkwrap.json'));
    const anyLock = hasLock || ['yarn.lock', 'pnpm-lock.yaml', 'bun.lock', 'bun.lockb'].some((f) => fs.existsSync(path.join(root, f)));
    // No lockfile: the packages can't be checked (and each install may pull other code). Say so.
    if (fs.existsSync(path.join(root, 'package.json')) && !anyLock) {
        findings.push({ severity: 'info', rule: 'no-lockfile', file: 'package.json',
            title: 'Dependencies not checked: no lockfile',
            why: 'Without a lockfile the exact package versions are not pinned, so known security holes in them can\'t be checked, and every install may pull different code.',
            fix: FIX.noLock });
    }
    if (opts.audit && hasLock) {
        const a = runNpmAudit(root, { exec: opts.auditExec, timeoutMs: opts.auditTimeoutMs });
        if (!a.ok) {
            findings.push({ severity: 'info', rule: 'audit-skipped', file: 'package-lock.json',
                title: `The dependency check did not finish (${a.reason})`,
                why: 'Known security holes in packages could not be checked this time.',
                fix: 'Run `npm audit --omit=dev` yourself when you are online.' });
        } else {
            const { critical = 0, high = 0, moderate = 0 } = a.counts;
            const named = a.names.length ? ` (${a.names.slice(0, 5).join(', ')}${a.names.length > 5 ? '…' : ''})` : '';
            if (critical + high > 0) {
                findings.push({ severity: 'warning', rule: 'npm-audit', file: 'package-lock.json',
                    title: `${critical + high} package${critical + high === 1 ? '' : 's'} with known serious security holes${named}`,
                    why: 'These are published, known weaknesses in code your site runs; attackers scan for them.',
                    fix: FIX.audit });
            } else if (moderate > 0) {
                findings.push({ severity: 'info', rule: 'npm-audit', file: 'package-lock.json',
                    title: `${moderate} package${moderate === 1 ? '' : 's'} with moderate known issues`,
                    why: 'Lower risk, but worth updating when convenient.', fix: FIX.audit });
            }
        }
    }

    const order = { critical: 0, warning: 1, info: 2 };
    findings.sort((a, b) => order[a.severity] - order[b.severity] || String(a.file).localeCompare(String(b.file)) || (a.line || 0) - (b.line || 0));
    const counts = { critical: 0, warning: 0, info: 0 };
    for (const f of findings) counts[f.severity]++;
    return {
        ok: counts.critical === 0, blocked: counts.critical > 0, counts, findings,
        scanned: { files: files.length, git: isGit, outDirs: outDirs.map((d) => path.relative(root, d) || '.'), audit: !!(opts.audit && hasLock) },
    };
}

export function formatReport(r) {
    const L = [];
    const label = { critical: 'CRITICAL', warning: 'WARNING', info: 'INFO' };
    L.push(`Security check before deploy — ${r.counts.critical} critical, ${r.counts.warning} warning, ${r.counts.info} info (${r.scanned.files} files${r.scanned.outDirs.length ? ', publish folder: ' + r.scanned.outDirs.join(', ') : ''})`);
    if (!r.findings.length) { L.push('No problems found.'); return L.join('\n'); }
    for (const sev of SEVERITIES) {
        const group = r.findings.filter((f) => f.severity === sev);
        if (!group.length) continue;
        L.push('', `${label[sev]} (${group.length})`);
        for (const f of group) {
            L.push(`- ${f.title}${f.file ? ` — ${f.file}${f.line ? ':' + f.line : ''}` : ''}${f.count > 1 ? ` (+${f.count - 1} more in this file)` : ''}${f.evidence ? ` [${f.evidence}]` : ''}`);
            L.push(`  Why: ${f.why}`);
            L.push(`  Fix: ${f.fix}`);
        }
    }
    L.push('', r.blocked ? 'BLOCKED: fix the Critical items, or the person must explicitly say "deploy anyway".' : 'No Critical items — OK to deploy.');
    return L.join('\n');
}

// CLI
const isMain = (() => { try { return process.argv[1] && fs.realpathSync(process.argv[1]) === fs.realpathSync(fileURLToPath(import.meta.url)); } catch { return false; } })();
if (isMain) {
    const args = process.argv.slice(2);
    const opt = { audit: args.includes('--audit') };
    const oi = args.indexOf('--out');
    if (oi >= 0) opt.outDir = args[oi + 1];
    const dir = args.find((a, i) => !a.startsWith('--') && args[i - 1] !== '--out') || process.cwd();
    try {
        const r = scanProject(dir, opt);
        process.stdout.write((args.includes('--json') ? JSON.stringify(r, null, 2) : formatReport(r)) + '\n');
        process.exit(r.blocked ? 2 : 0);
    } catch (e) {
        process.stderr.write('deploy-check failed: ' + (e?.message || e) + '\n');
        process.exit(1);
    }
}

