#!/usr/bin/env python3
"""Markdown → PDF next to it (same name, .pdf), for documents a person reads.

Usage:
    python3 md_to_pdf.py <file.md> [more.md ...]

Renders the Markdown (tables, code, mermaid diagrams) in a print-styled page and
prints it with a headless Chrome / Chromium / Edge. If no browser is found, leaves
<name>.print.html instead — the app offers one-click "Save as PDF" for those.
Returns the list of files written; exit code 0 either way (never blocks a deliverable).
"""
import json
import re
import os
import shutil
import subprocess
import sys
from pathlib import Path

PAGE = """<!doctype html><html><head><meta charset="utf-8"><title>%(title)s</title>
<style>
@page { size: A4; margin: 16mm 15mm; }
body { font: 10.5pt/1.5 -apple-system, "Segoe UI", Helvetica, Arial, sans-serif; color: #1c2230; }
h1 { font-size: 20pt; color: #3a3fd6; border-bottom: 3px solid #3a3fd6; padding-bottom: 6px; margin-top: 0; }
h2 { font-size: 14pt; color: #2a2f8a; margin-top: 22px; border-bottom: 1px solid #d9dcf3; padding-bottom: 3px; page-break-after: avoid; }
h3 { font-size: 12pt; color: #2a2f8a; page-break-after: avoid; }
table { border-collapse: collapse; width: 100%%; margin: 8px 0 12px; font-size: 9.5pt; page-break-inside: avoid; }
th, td { border: 1px solid #d5d9e6; padding: 5px 7px; text-align: left; vertical-align: top; }
th { background: #eef0fb; }
code { background: #f1f2f7; padding: 1px 4px; border-radius: 3px; font-size: 9pt; }
pre { background: #f6f7fb; border: 1px solid #e1e4ef; padding: 8px 10px; border-radius: 5px; white-space: pre-wrap; font-size: 8.8pt; page-break-inside: avoid; }
pre code { background: none; padding: 0; }
p { margin: 6px 0; }
.mermaid { text-align: center; margin: 10px 0; page-break-inside: avoid; }
a { color: #3a3fd6; }
</style>
<script src="https://cdn.jsdelivr.net/npm/marked@12.0.2/marked.min.js" integrity="sha384-/TQbtLCAerC3jgaim+N78RZSDYV7ryeoBCVqTuzRrFec2akfBkHS7ACQ3PQhvMVi" crossorigin="anonymous"></script>
<script src="https://cdn.jsdelivr.net/npm/mermaid@11.4.1/dist/mermaid.min.js" integrity="sha384-rbtjAdnIQE/aQJGEgXrVUlMibdfTSa4PQju4HDhN3sR2PmaKFzhEafuePsl9H/9I" crossorigin="anonymous"></script>
</head><body><div id="doc"></div>
<script>
const md = %(md)s;
const esc = (t) => t.replace(/&/g, '&amp;').replace(/</g, '&lt;');
if (window.marked) {
  const r = new marked.Renderer();
  r.code = (code, lang) => lang === 'mermaid' ? '<div class="mermaid">' + code + '</div>' : '<pre><code>' + esc(code) + '</code></pre>';
  document.getElementById('doc').innerHTML = marked.parse(md, { renderer: r, breaks: true });
  // A key/value table written with an empty header row: drop that row.
  document.querySelectorAll('thead tr').forEach((tr) => { if ([...tr.cells].every((c) => !c.textContent.trim())) tr.remove(); });
} else {
  document.getElementById('doc').innerHTML = '<pre>' + esc(md) + '</pre>';
}
if (window.mermaid) { mermaid.initialize({ startOnLoad: false, theme: 'neutral' }); mermaid.run({ querySelector: '.mermaid' }); }
</script></body></html>"""

BROWSERS = [
    "google-chrome", "chromium", "chromium-browser", "msedge", "chrome",
    "/Applications/Google Chrome.app/Contents/MacOS/Google Chrome",
    "/Applications/Microsoft Edge.app/Contents/MacOS/Microsoft Edge",
    "/Applications/Chromium.app/Contents/MacOS/Chromium",
    r"C:\Program Files\Google\Chrome\Application\chrome.exe",
    r"C:\Program Files (x86)\Google\Chrome\Application\chrome.exe",
    r"C:\Program Files (x86)\Microsoft\Edge\Application\msedge.exe",
    r"C:\Program Files\Microsoft\Edge\Application\msedge.exe",
]


def headless_shell():
    """Playwright's chrome-headless-shell, newest first: it prints PDFs without a Dock /
    taskbar icon, which a full Chrome — even headless — leaves behind on every run."""
    import glob
    home = Path.home()
    pats = [home / "Library/Caches/ms-playwright", home / ".cache/ms-playwright", home / "AppData/Local/ms-playwright"]
    found = []
    for base in pats:
        for p in glob.glob(str(base / "chromium_headless_shell-*" / "chrome-headless-shell-*" / "chrome-headless-shell*")):
            m = re.search(r"chromium_headless_shell-(\d+)", p)
            if m and os.path.isfile(p) and os.access(p, os.X_OK):
                found.append((int(m.group(1)), p))
    return max(found)[1] if found else None


def find_browser():
    shell = headless_shell()
    if shell:
        return shell
    for b in BROWSERS:
        p = shutil.which(b) if not os.path.isabs(b) else (b if os.path.exists(b) else None)
        if p:
            return p
    return None


def md_to_pdf(md_path):
    md_path = Path(md_path)
    html_path = md_path.with_suffix(".print.html")
    pdf_path = md_path.with_suffix(".pdf")
    html_path.write_text(PAGE % {"title": md_path.stem, "md": json.dumps(md_path.read_text())}, encoding="utf-8")
    browser = find_browser()
    if browser:
        try:
            subprocess.run([browser, "--headless=new", "--disable-gpu", "--no-pdf-header-footer",
                            "--virtual-time-budget=15000", f"--print-to-pdf={pdf_path.resolve()}",
                            html_path.resolve().as_uri()],
                           stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, timeout=120)
        except (OSError, subprocess.SubprocessError):
            pass
    if pdf_path.exists() and pdf_path.stat().st_size > 0:
        html_path.unlink(missing_ok=True)
        return pdf_path
    return html_path  # fallback: open it and Save as PDF


def main(argv):
    if len(argv) < 2:
        print("usage: md_to_pdf.py <file.md> [more.md ...]", file=sys.stderr)
        return 1
    for a in argv[1:]:
        print(f"wrote: {md_to_pdf(a)}")
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

