    /\bexport\s+const\s+(?:dynamic|revalidate)\b/.test(haystack) ||
    /\b(?:set|add|configure|use)\s+[^.\n]{0,80}\b(?:dynamicParams|fetchCache)\b/i.test(haystack) ||
