              pattern: metadata.id,
              subtype: 'image-svg-no-unoptimized',
              file: path,
              line: lineOf(content, m.index),
              evidence: tag.slice(0, 200),
              trafficIndependent: metadata.trafficIndependent,
            });
          }
        }
      }
