export function escapeRegex(s) {
  return s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

// `slow_route:/api/products` → `/api/products`.
export function extractRoute(rec) {
  if (typeof rec?.candidateRef !== 'string') return null;
  const m = rec.candidateRef.match(/^[^:]+:(.+)$/);
  return m ? m[1] : null;
}

